-- El camino de Sherlock -- PARTE 2 de 2. En orden.

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'el-camino-de-sherlock',
  20,
  'Parte 21',
  $lira$[{"type": "p", "text": "—No es cierto —dije sin levantar la vista de lo que estaba haciendo—. ''Aunque mostraba un cierto esmero discreto en su manera de vestir, en sus hábitos personales era uno de los hombres más desordenados que jamás hayan llevado a la desesperación a un compañero de pensión\". El ritual de los Musgrave."}, {"type": "p", "text": "Ella me miró nerviosa."}, {"type": "p", "text": "—¿Qué?"}, {"type": "p", "text": "—Lo dice Watson sobre Holmes en el cuento El ritual de los Musgrave."}, {"type": "p", "text": "—Ajá."}, {"type": "p", "text": "Creo que se estaba desesperando. También en la escuela la situación se volvía cada vez más difícil. Los chicos de cursos inferiores habían empezado a buscarme en los recreos. Querían que les diera autógrafos, que les firmara dibujos que habían hecho sobre Holmes y Watson o simplemente mirarme de cerca. Al cabo de unos días no lo pude soportar más y empecé a rechazar los: escondía la cara tras un libro y decía que no me molestaran, porque estaba ocupado. Arturo se mostró claramente molesto un día en que eché sin contemplaciones a un chico de segundo grado que pareció quedar al borde del llanto."}, {"type": "p", "text": "—Si no te conociera tan bien, Sherlock, pensaría quesos un idiota. Pero creo que te portás así por la tensión. Me parece a mí que estás muerto de miedo. ¿O no?"}, {"type": "p", "text": "-\"Querido Watson, aquí entrarnos en el terreno de las conjeturas, donde la mente más lógica puede fracasar\". La aventura de la casa vacía."}, {"type": "p", "text": "—Me tenés hano con tus citas —dijo levantándose—. Podrido."}, {"type": "p", "text": "Pero fue en el canal donde llegué a mi punto más bajo, a la verdadera muestra de mi decadencia moral. Todos teníamos la costumbre de llevar algún texto para repasar en los largos tiempos que debíamos esperar para salir al aire. Aquella tarde, Violeta estaba concentrada en un nuevo tratado sobre arañas, Ignacio leía una lista de preguntas que su padre había confeccionado para ayudarlo y yo repasaba una biografía . de Conan Doyle. De pronto Ignacio levantó la vista de sus papeles y me miró."}, {"type": "p", "text": "—Ayax el Menor —dijo—. Era hijo de ... No estoy seguro. ¿Oileo?"}, {"type": "p", "text": "—¿Oileo? —repetí yo frunciendo el ceño y meneando suavemente la cabeza. No sé por qué lo hice. Al fin y al cabo, yo no tenía la más pálida idea de. quién era Ayax. Pero él interpretó mi gesto como un indicio de error."}, {"type": "p", "text": "—No, no... Es cierto —dijo enseguida—. Es hijo de ... Deucalión. Debe de ser Deucalión."}, {"type": "p", "text": "—Puede ser —asentí—. Deucalión. Empezó a revisar un libro, pero en ese momento vinieron a decirnos que pasáramos al estudio: el· programa estaba por empezar. Violeta se levantó y antes de salir me miró. Me pareció que esa mirada decía todo. Por supuesto, nada de ello habría tenido importancia de no ser porque esa fue, exactamente, la pregunta que tuvo que responder Ignacio minutos más tarde."}, {"type": "p", "text": "Primero Corelli hizo una introducción que intentaba darle emoción a la jornada. Dijo que nos estábamos acercando al final, que las preguntas ya eran mucho más complejas y que al final de esa emisión todos conocerían el nombre de los fina listas: los dos que se batirían por el gran premio. Luego se volvió hacia Ignacio y sacó el papel del sobre."}, {"type": "p", "text": "—En la Ilíada aparecen dos personajes de nombre Ayax. Uno es Ayax el Grande, hijo de Telamón, rey de Salamina. El otro es Ayax el Menor. ¿De quién es hijo este último? Vi que Ignacio se ponía muy serio. Se tomó unos segundos y después contestó con voz temblorosa."}, {"type": "p", "text": "—De Deucalión."}, {"type": "p", "text": "Micky Corelli se mordió el labio inferior."}, {"type": "p", "text": "—No. Lo siento. Ayax el Menor era hijo de Oileo, rey de Locris."}, {"type": "p", "text": "No quise mirar a Ignacio cuando se fue . .E n los años que siguieron pensé muchas veces en este incidente. Repasé todos los detalles del diálogo y me consolé pensando que yo no lo engañé ni le mentí, que fue él quien eligió darle a mi gesto un sentido definitivo que no tenía. Pero también sé que, cuando Ignacio me interrogó, yo debería haber dicho algo tan simple como \"no sé\". Esas dos palabras vulgares que dice la gente todo el tiempo. Solo que los demás nunca esperan que yo las diga: supo nen que siempre sé lo que hay que saber. Lo que nunca podré olvidar es la mirada de Violeta. Creo que me va a perseguir hasta el final de mi vida."}]$lira$::jsonb,
  719
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'el-camino-de-sherlock',
  21,
  'Parte 22',
  $lira$[{"type": "p", "text": "Diez · días después dd asesinato de María Luisa Reyes la calma parecía haber vuelco al barrio de Belgrano. Si bien la gente de la zona seguía mirando obsesivamente a derecha e izquierda antes de entrar a su casa y recelando de cualquier motociclista que le pasara cerca, la opinión generalizada era que la fuerte presencia policial había disuadido al asesino de hacer nuevos movi mientos. La tensión iba cediendo y otros temas empezaron a desplazar a los crímenes de las primeras planas. Cualquiera hubiera dicho que la crisis se había terminado. Todo cambió bruscamente en el día once. Pasaba la medianoche cuando José Luis Míguez llegó a su casa de la calle Carbajal luego de una tardía cena de trabajo. Le llamó la atención una luz que salía de lo de su vecina: la puerta parecía estar levemente abierta. Se acercó a las rejas y la llamó."}, {"type": "p", "text": "—¿Lucía?"}, {"type": "p", "text": "No hubo respuesta. Según explicaría después, Míguez la conocía desde que era niña, había sido amigo de su padre y,-ahora que ella vivía sola, se sentía un poco responsable. Por eso, en lugar de irse a dormir sin pensar más en el asunto, tocó el timbre dos veces. Esperó unos segundos, pero no"}, {"type": "p", "text": "nadie atendió. Su visión de la puerta ~ra buena, ya que la casa tenía un pequeño jardín;d elantero y el ponón de rejas que la separaban de la callé. Además, la iluminación era difusa y el señor Míguez, bastante miope. Aun así, desde su punto de observación le pareció que habfa algo en el piso que impedía que la puena se cerrara. Cuando se tomó de la reja, notó que el ponón no estaba con llave, sino apenas apoyado. Lo abrió. Mientras avanzaba por el pequeño jardín volvió a llamar:"}, {"type": "p", "text": "—¿Lucía?"}, {"type": "p", "text": "Fue entonces cuando llegó a la puerta y se dio cuenta de que lo que impedía que se cerrara eran, precisamente, los pies de su vecina. Lucía Bernárdez yacía en la entrada de su casa con dos balazos en el pecho."}, {"type": "p", "text": "Tenía apenas veinticinco años. Según la información recogida por los medios, había sido asesinada cuando volvía a su casa desde la universidad, poco después de las diez. Aún llevaba puesto el abrigo, y la cartera había quedado tirada a su lado. La puerta no estaba forzada, de lo cual se dedujo que la habían obligado a abrir y había muerto apenas cruzado el umbral. Tampoco en este caso el robo era el motivo: en la casa no parecía faltar nada. El asesino ni siquiera había revisado la cartera de Lucía, donde había dinero, tarje tas de crédito y un celular. Esta vez no esperé al día siguiente para leerlo en el diario: la noticia acaparó la atención de la ciudad y fue casi imposible ignorarla. La calle Carbajal se llenó de periodistas, curiosos y escandalizados vecinos que expresaban a los gritos su descontento con una policía incapaz de frenar la ola de muertes. Las cámaras mostraron un desfile de dolidos amigos de la víctima, que la describieron como una chica tranquila y alegre, que jamás había tenido un enemigo. Dos años atrás había muerto su padre y desde ese momento vivía sola en la casa familiar. Estaba a punto de terminar la carrera de Antropología. Al parecer, por el momento no necesitaba trabajar: contaba con un interesante patrimonio. Tenía un novio de muy buen aspecto y un viaje a París en puertas. Uno podía deducir, en suma, que hasta el instante en que se topó con su asesino la vida le venía sonriendo a Lucía Bernárdez."}]$lira$::jsonb,
  590
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'el-camino-de-sherlock',
  22,
  'Parte 23',
  $lira$[{"type": "p", "text": "En los días siguientes no se habló de otra cosa. Un hombre que vivía enfrente contó que volvía a su casa, a las diez y diez, cuando se cruzó con una moto: la había observado con atención, porque desde \"los incidentes\" intentaba alejarse cada vez que veía una. El conductor llevaba casco e impermeable oscuro, aseguró. El dato coincidía con una huella encontrada en la puerta de la casa de Lucía. Como había llovido buena parte de la tarde, las calles estaban embarradas y el rastro era bastante claro: se trataba de un tipo de neumático vulgar, del que llevan millones de motos en la ciudad. No se hallaron, en cambio, señales de pelea ni huellas digitales. Al parecer, Lucía no había alcanzado a defenderse. La autopsia reveló, casi previsi blemente, que las balas eran de calibre .380. Hubo un elemento que la policía se guardó varios días, quizá previei:ido el impacto que genera ría: junto al cuerpo de la chica, además de su carte ra, habían encontrado una bolsa del supermercado El Amanecer. Adentro había un paquete de arroz. Se trataba, según la interpretación que inmediatamente corrió de boca en boca, de una suerte de \"firma'' del asesino. Un claro gesto de desafío a quienes no lograban atraparlo. También fue un dolor de cabeza parad pobre señor Huang, ya que pronto sus dientes empezaron a abandonarlo. Se instaló la idea de que quien compraba allí corría el riesgo de ser asesinado. Finalmente, un día el supermercado apareció cerrado, con un cartel que anunciaba su traslado hacia otro barrio. A mí el asunto de la bolsa junto al cadáver no me sorprendió demasiado. Me pareció, eso sí, que los métodos del asesino se estaban volviendo un poco obvios."}, {"type": "p", "text": "Las reacciones a partir de entonces llega ron al punto de histeria. Si ya antes el barrio había estado conmocionado, con este último asesinato la situación se volvió ingobernable. Todos los días había marchas que reclamaban más seguridad. Muchas mujeres se resistían a dejar sus casas y algunas escuelas decidieron cerrar hasta que cam biaran las cosas. RC$taurantes y heladerías tuvieron que enviar los pedidos con repartidores en bicicleta, porque los clientes se negaban a abrirle la puerta a alguien que llegara en moto. Los pocos que se atrevían a conducir esos vehículos lo hacían sin casco, para que les vieran la cara. De lo contra rio, se arriesgaban a ser linchados. Se empezó a rumorear que el jefe de policía y quizá también el ministro del Interior iban a caer por la incompe tencia manifiesta de las fuerzas de seguridad para atrapar al \"asesino de la moto\". Porque así fue apodado por los medios."}, {"type": "p", "text": "Yo, sin embargo, no compartí en absoluto esta sensación generalizada de pánico. No es mi estilo. Lo más parecido al pánico que sentí alguna ve:z fue en la etapa final del concurso. Los"}, {"type": "p", "text": "días previos a la gran final fueron una tortura para mí. La inminencia del desenlace había desatado una catarata de notas en distintos medios periodísticos. Cuando más hubiera querido desaparecer, mi cara surgía en todas partes. Según pude ver, las preferencias entre Violeta y yo estaban divididas. Creo que ella tenía dos cosas importantes a su favor. La primera era su belleza. La segunda, la forma dulce en que hablaba de sus asquerosas arañas, un tema que despenaba una oscura fascinación en la gente. En mi caso, supongo que lo principal era mi pequeñez. Mi reducido tamaño provocaba en muchas personas la sensación de estar frente a un fenómeno o, como dijo un periodista completa mente confundido en una radio, \"un futuro Einstein\". Yo trataba de no prestar mucha atención a ese tipo de notas para evitar sentirme descom puesto, si bien no era fácil obviar el despliegue que hacía mamá en casa cuando las recortaba, las clasi fkaba y las colocaba prolijamente en carpetas. Una tarde, cuando llegué de la escuela, la encontré cortando una que llevaba por título: \"La Chica Araña versus Sherlock: ¿quién ganará?\" Detuvo mi camino hacia la cocina para anunciar me que habían llamado de un diario y una revista pidiendo entrevistas conmigo. La revista proponía hacerme fotos con pipa, gorro y lupa."}, {"type": "p", "text": "—Ellos traerían todo —aclaró."}, {"type": "p", "text": "—No."}, {"type": "p", "text": "—¿No qué? ¿Te molestan las fotos?"}, {"type": "p", "text": "—No a todo. Ni loco."}]$lira$::jsonb,
  710
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'el-camino-de-sherlock',
  23,
  'Parte 24',
  $lira$[{"type": "p", "text": "Dos días después, al llegar a casa la encontré en la sala conversando con una chica mientras un tipo le sacaba fotos. Sobre la mesa estaba el álbum de cuando yo era bebé y ella pasabalas páginas mientras contaba anécdotas. Había ido a la peluquería y llevaba un vestido nuevo. Cuando nuestras miradas se cruzaron me hizo un gesto para que me acercara, pero yo huí a mi habitación."}, {"type": "p", "text": "Esa noche me dijo que lo había hecho por mí."}, {"type": "p", "text": "—Pensé que era bueno que alguien diera la entrevista, para que no cayeran tus posibilidades. La chica está saliendo por todos lados."}, {"type": "p", "text": "—Mis posibilidades no dependen de las notas —dije—. Lo hiciste porque te gusta salir en las revistas."}, {"type": "p", "text": "Durante unos instantes me miró sin decir nada. Me di cuenta de que la había herido."}, {"type": "p", "text": "—No es así —se defendió levantando la voz—, yo hago todo ..."}, {"type": "p", "text": "No escuché el final de la frase: el golpe que di al cerrar la puerta de mi habitación me lo impidió. Después me arrepentí. No tanto por el efecto que pudo provocar en ella, sino porque odio perder el control de mis emociones. Pese a lo mal que venía tratándolo, Watson demostró ser un buen amigo y se ofreció a instalarse en mi casa la noche anterior para ayudarme en lo que fuera necesario. Era un ofrecimiento generoso, teniendo en cuenta que yo me había convertido en un ser huraño y desagradable que pasaba las horas vagando por la casa mientras repetía citas como un autómata. Cuando llegó, yo tenía preparada la pila de libros. Le pedí que los fuera abriendo al azar y me preguntase cualquier cosa de la trama o los personajes. Acerté en casi todo: decenas de preguntas. Pero tropecé en dos, y cada vez sentí que ante mí se abría un abismo que me chupaba hacia el fondo."}, {"type": "p", "text": "—Voy a perder —le dije—. Estoy seguro."}, {"type": "p", "text": "—No —contestó, aunque estaba visiblemente preocupado—. Solo tenés que serenarte. La presión te mata."}, {"type": "p", "text": "Un rato más tarde mi madre nos llamó a cenar. Puso un bife con papas fritas ante cada uno de nosotros, pero yo tenía el estómago cerrado. Aparté el plato."}, {"type": "p", "text": "—No comiste en todo el día —advirtió mi madre y volvió a acercármelo."}, {"type": "p", "text": "—Mejor —dije y lo alejé."}, {"type": "p", "text": "—Sin comida el cerebro no te funciona —intervino Arturo y lo empujó otra vez hacia mí."}, {"type": "p", "text": "—No es cierto —volví a alejarlo—. \"Las facultades se refinan cuando se está muy ham briento. Porque seguramente como doctor, mi querido Watson, debe admitir que la digestión gana en abastecimiento de sangre tanto como pierde el cerebro. Yo soy un cerebro, Watson. El resto de mí es meramente un apéndice\". La aventura de la, piedra preciosa de Mazarino."}, {"type": "p", "text": "—Estupideces —contestó mientras acercaba el plato una vez más—. Así corrés el riesgo de desmayarte en el medio del programa. Algo tenés que comer."}, {"type": "p", "text": "Pensé que en eso quizá tenía razón y me comí las papas fritas."}, {"type": "p", "text": "Seguimos con las preguntas hasta la media noche. Me equivoqué dos veces más. Cuando finalmente apagamos la luz, me sentía como un trapo de piso. Bien podrían haber limpiado el baño con mi estado de ánimo."}, {"type": "p", "text": "—Buenas noches —dijo Arturo. -\"Diga, Watson —susurré en la oscuridad—, ¿estaría asustado de dormir en la misma habitación que un lunático, un hombre con reblandecimiento cerebral, un idiota cuya mente ha perdido su filo?\"."}, {"type": "p", "text": "—¿H olmes dice eso?"}, {"type": "p", "text": "—Sí. En El valle del terror."}, {"type": "p", "text": "—Tu cerebro está bien, Sherlock, solo tenés que dormir un poco."}, {"type": "p", "text": "Pero yo sabía que no era cierto. Violeta ya estaba en la sala cuando entré. Creo que los dos percibimos en el mismo momento lo incómodo de la situación. Cuando éramos varios, la sensación de enemistad se diluía, pero ahora era imposible no pensar que estábamos en guerra. Esa tarde uno de los dos saldría triunfante y el otro querría morirse. Por suerte, ella sacó el tema."}, {"type": "p", "text": "—Mirá, Sherlock -<lijo dejando su libro en la mesa—. Yo creo que vas a ganar vos. Al fin y al cabo, todos dicen quesos un genio. Pero no me importa. O sí —se corrigió—, me importa, pero está bien. Eso quiero decirte: que está bien. Me gustó que lo dijera."}, {"type": "p", "text": "—Yo pienso que vas a ganar vos —contes té—. Y sí, está bien. Que sea como sea. Me dio la mano. Fue raro, como si estu viéramos cerrando un trato que no tenía conciencia de haber hecho."}]$lira$::jsonb,
  734
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'el-camino-de-sherlock',
  24,
  'Parte 25',
  $lira$[{"type": "p", "text": "Poco después pasamos al estudio. Corelli estaba peor que nunca, en una suerte de histérica excitación que lo hacía correr de un lado al otro del lugar disponiendo todo para empezar y soltando chistes cada vez más tontos. Habían planifica do que la competencia final sería rápida, una suerte de ping-pong de preguntas a ritmo frenéti co. Empezó dirigiéndose a Violeta."}, {"type": "p", "text": "—La araña Latrodectus mactans recibe un nombre popular muy conocido. ¿Cuál es y a qué se debe?"}, {"type": "p", "text": "—Viuda negra. La llaman así porque generalmente se come al macho después del apareamiento."}, {"type": "p", "text": "—¡Exacto!"}, {"type": "p", "text": "Amí:"}, {"type": "p", "text": "—En Estudio en escarlata aparece, en la escena del crimen, una palabra escrita con sangreen la pared. ¿Cuál es esa palabra y qué significa?"}, {"type": "p", "text": "—Rache. Significa \"castigo\" en alemán."}, {"type": "p", "text": "—¡Exacto!"}, {"type": "p", "text": "A ella:"}, {"type": "p", "text": "—¿Qué son los pedipalpos?"}, {"type": "p", "text": "—Son los dos apéndices sensoriales que tienen las arañas en el cefalotórax:."}, {"type": "p", "text": "—¡Exacto!"}, {"type": "p", "text": "Amí:"}, {"type": "p", "text": "—Tras la fama obtenida con Sherlock Holmes, a Arthur Conan Doyle le pidieron que investigara un caso real: el de un hombre que había sido acusado injustamente de una serie de crímenes. ¿Cómo se llamaba ese hombre?"}, {"type": "p", "text": "—George Edalji."}, {"type": "p", "text": "—¡Exacto!"}, {"type": "p", "text": "A ella:"}, {"type": "p", "text": "—Hay una araña domiciliaria peligrosa a la que se llama vulgarmente \"araña de los cuadros\" o \"araña de los rincones\" porque se refugia en lugares oscuros. ¿Cuál es su nombre científico? Hubo un silencio. Violeta parecía dudar y, por un segundo, pensé que había ganado yo. Mi corazón empezaba a agitarse cuando ella se recuperó."}, {"type": "p", "text": "—Loxosceles /aeta."}, {"type": "p", "text": "—¡Exacto!"}, {"type": "p", "text": "Amí:"}, {"type": "p", "text": "—Sherlock Holmes dice en una oportunidad que hay una persona cuyos poderes de observación son mejores que los suyos. ¿Quién es?"}, {"type": "p", "text": "—Su hermano Mycroft."}, {"type": "p", "text": "—¡Exacto!"}, {"type": "p", "text": "A ella:"}, {"type": "p", "text": "—¿Cómo se llama el proceso por el cual las arañas se desprenden periódicamente de su esqueleto externo?"}, {"type": "p", "text": "—Muda o ecdisis."}, {"type": "p", "text": "—¡Exacto!"}, {"type": "p", "text": "Amí:"}, {"type": "p", "text": "—Watson aparece mencionado como el doctor John H. Watson. ¿Cuál es ese segundo nombre que empieza con hache? Me quedé callado. El abismo se estaba abriendo. ¿Cómo no sabía yo algo tan tonto como el segundo nombre de Watson? Vagamente me sonó Henry. ¿O Henry era su padre? El tiempo pasaba. El abismo me estaba tragando. • —Henry."}, {"type": "p", "text": "Silencio. Yo caía al abismo. No había de dónde agarrarse. Corelli cerró un instante los ojos, como si sufriera, y después dijo muy lentamente:"}, {"type": "p", "text": "—Lo siento, Francisco, el nombre es Hamish."}, {"type": "p", "text": "En los minutos siguientes fui vagamente consciente de que todos los compañeros de Violeta gritaban, se le echaban encima y después la paseaban en andas. Había llegado al fondo del abismo. La hache de Watson, ¿cómo no iba a saber eso? Mi madre surgió de la nada, me apre tó el brazo y dijo que todo estaba bien, aunque en su cara todo estaba mal. Una pregunta tan idiota. Una hache. Mis compañeros aseguraron que lo importante era haber llegado ahí. Una hache. ¿Hamish? Mi madre dijo que agarrara mis cosas, que nos íbamos. Nunca había oído lo de Hamish. Watson me palmeó la espalda. Salimos a la calle. Estaba oscuro. Hamish, Hamish, Hamish. ¿Cómo no lo supe?"}, {"type": "p", "text": "Se me cruzó una cita por la cabeza: \"Es realmente gracioso verlo jugar una mano sin cartas. Creo que nadie lo haría mejor, pero resulta al mismo tiempo bastante patético. Mr Holrnes, no tiene usted en la mano ni un solo triunfo\". Se lo dice el barón Bruner a Sherlock en El cliente ilustre."}, {"type": "p", "text": "La detención de Armando Rosales tuvo lugar un jueves. Yo estaba terminando un informe para el colegio en el momento en que mamá, que miraba las noticias en la televisión, me gritó desde la sala:"}, {"type": "p", "text": "—Vení, Fran, esto te va a interesar. Cuando me acerqué unas letras tamaño catástrofe lo anunciaban en la pantalla: \"Detuvieron al asesino de la moto\". Dos policías estaban haciendo entrar a un hombre en un patrullero, pero no pude ver su cara porque tenía la cabeza tapada. Era alto y llevaba las manos esposadas en la espalda. No lo habían atrapado como resultado de una cuidadosa investigación, sino de pura casualidad. Rosales había ido a una ferretería en busca de una serie de materiales para confeccionar una estantería y se había metido en una violenta y absurda discusión con el dueño del local, a propósito del tono usado por el hombre al responderle sobre la forma de los tornillos. En un momento, un movimiento de su brazo hizo que su impermea ble se entreabriera y dejó al descubierto la parte superior de sus pantalones, donde un empleado alcanzó a ver un arma. Sigiloso, se escabulló hacia el fondo del local y llamó a la policía. Cuando salió a la calle a esperarlos, descubrió otra cosa que le pareció sumamente reveladora: la moto del cliente irascible."}]$lira$::jsonb,
  775
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'el-camino-de-sherlock',
  25,
  'Parte 26',
  $lira$[{"type": "p", "text": "Rosales intentó resistir la detención, pero tres policías lo inmovilizaron en el suelo. El arma era, como cabía esperar, una pistola Bersa calibre .380."}, {"type": "p", "text": "En los días siguientes, los diarios aporta ron todo tipo de detalles. Rosales tenía cuarenta y tres años, y había estado al menos dos veces internado en instituciones psiquiátricas. Los médicos que lo habían atendido hablaban de episodios de violencia y delirios paranoicos, en los que se imaginaba perseguido por el gobierno, la policía, sus vecinos, el FBI o una secta que se proponía dominar el mundo. Mientras vivió, su madre se había ocupado de controlar que siguiera su tratamiento, pero desde su fallecimiento Rosales estaba solo y al parecer había abandonado la medicación."}, {"type": "p", "text": "Alquilaba un pequeño departamento del barrio de Belgrano. Cuando fueron a realizar el allanamiento, los policías se encontraron con un oficial de justicia que en ese momento se disponía a ejecutar una orden de desalojo: Rosales llevaba ocho meses sin pagar el alquiler. Casi desde la muerte de su madre. El lugar estaba asquerosa mente sucio y lleno de recortes periodísticos. Algunos, pegados en las paredes, se referían a ase sinatos y otros hechos de violencia. También había fotos de mujeres llamativas arrancadas de revistas y una tabla con horarios del ferrocarril. Las pericias realizadas sobre el arma que llevaba con él mostraron que era la misma usada para disparar contra la confitería, pero no en los asesinatos. Sin embargo, se especuló con que el hombre tenía una segunda pistola, ya que había podido echar mano a las posesiones de un tío anciano que había sido coleccionista. Según una empleada de ese tío, que ahora estaba internado en un geriátrico, alguien había vaciado la vitrina donde guardaba las armas. Pero en el allanamien to esa segunda pistola no apareció. La declaración de Rosales fue contradicto ria y confusa, aunque al parecer llegó a reconocer al menos uno de los hechos. El defensor oficial que le adjudicaron anunció que pediría que lo declararan inimputable, ya que evidentemente el hombre no podía distinguir entre el bien y el mal. Cinco días después de la detención se hizo una rueda de reconocimiento con los dos muchachos que se lo habían cruzado en la estación de tren. Uno dudó, pero el segundo lo identificó cla ramente. Eso pareció una prueba definitiva. La calma volvió poco a poco a Belgrano. Ya habían pasado quince días desde el asesinato de Lucía Bernárdez sin ningún otro incidente violento. Para todo el mundo parecía claro que el asesino de la moto estaba tras las rejas. Para mí, en cambio, las cosas estaban cada vez más oscuras. Yo dudaba de todo lo que se decía. Pero también dudaba de mi propia capacidad de análisis."}, {"type": "p", "text": ". . . , . . -~ r.. - ., -"}, {"type": "h", "text": "Ij"}]$lira$::jsonb,
  465
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'el-camino-de-sherlock',
  26,
  'Parte 27',
  $lira$[{"type": "p", "text": "iJ na de las consecuencias de mi derrota en el concurso fue la fuerte sensación de que mi inteligencia había declinado de forma irreparable. Sé que poca gente estaría de acuerdo con esta eva luación. Sin ir más lejos, si alguien consultara a mis compañeros de entonces, ellos dirían que en realidad yo resulté triunfador. Es que después de aquella gran final hubo una serie de inesperados sucesos con derivaciones aún más inesperadas. Lo primero fue una carta escrita por un profesor universitario, estudioso de la obra de Conan Doyle, y publicada en un diario muy serio. Allí sostenía que en el programa nunca se debió formular la pregunta que había provocado mi derrota, porque en realidad no se sabe con precisión ruál era el nombre en el que pensaba el autor cuando escribió la hache de John H. Watson. Si uno repasa codos los libros protagonizados por Sherlock Holmes, decía el experto, verá que en ninguno aparece ese segundo nombre. Han sido los \"círculos holmesia nos\" británicos, minuciosos analistas de la obra, los que, a través de una serie de conjeturas que sería tedioso reproducir, llegaron a la conclusión de que ese nombre podía ser Hamish. Algunas enciclope dias recogieron esa idea, por lo cual es posible encontrar biografías de Watson donde aparece como John Hamish. Pero siendo esa una especulación —seguía la carta-nadie podría asegurar que en realidad Conan Doyle no pensaba en \"Henry''. O sea, mi respuesta. La contundencia de la carta les permitió a las autoridades de mi escuela y a mi madre quejarse ante el canal por la arbitrariedad de la decisión que me había eliminado. También fue usada por pro gramas de la competencia para hacer comentarios maliciosos sobre los productores de \"Exacto\". Como si no tuvieran suficiente con eso, surgió un segundo debate, esta vez alimentado por educado res y psicólogos que criticaban que se empujara a niños aún en la escuela primaria a un concurso que los sometía a brutales niveles de estrés y de enfren tamiento. Viendo que su posición hacía agua por todos lados, la gerencia del canal tomó el asunto en sus manos y emitió, en un mismo día, dos anuncios: que el concurso volvía a ser para estudiantes de secundaria y que, visto el cuestionamiento reali.: za.do a la pregunta sobre Watson, compensarían a mi curso con un viaje a Bariloche para todos. Al día siguiente, mis compañeros me lleva ron en andas por la escuela, una situación franca mente incómoda. Pero para mí nada había cambiado. Me explico: ahora sabía que la pregunta era tramposa y que no debieron eliminarme. Pero el punto no era ese. El punto era que yo no lo había pensado. ¿Cómo puede ser que una persona que dedica hora tras hora y día tras día a leer las historias de Holmes para captar todos los detalles no se pregunte nunca a qué nombre responde esa letra? Viéndolo retrospectivamente, me parecía que esa enigmática hache reiterada de un libro a otro pedía a gritos una pregunta, como si estuviera emitiendo destellos luminosos. Haberla ignorado sólo podía hablar de un cerebro lento, dormido, carente de reflejos. Es algo que nunca le hubiese sucedido al propio Sherlock Holmes. Esa idea me llevó a otra, muy anterior: la sensación de que siempre fui sobrevalorado. Quizás el diamante del que les hablaron a mis padres ha ido perdiendo su brillo. O quizá siempre fue un diamante falso. Lo que descubrí con dolor en los dos años que siguieron es que no hay manera de estar a la altura de las expectativas que tienen los demás si creen que uno es un genio. Pasados los primeros meses, en que las relaciones con mis compañeros aún estaban teñidas por la alegría que les había dado al conseguir el viaje, las cosas volvieron a la normalidad. La mayor parte del tiempo parecían rehuirme. Supongo que yo debía de ser en parte culpable de esto, pero nunca entendí bien qué era lo que hacía para producir ese efecto. Tenía la impresión de que ellos solo se me acercaban cuando necesitaban la respuesta a alguna duda. Si no podía dársela, creían que era por alguna cuestión personal con ellos. Y luego estaban sus miradas cu.ando yo me equivoca ba en algo, cualquier cosa. Iban del estupor al placer. Había uno en particular, Edgardo Quinteros. Creo que él quería demostrar a toda costa que yo era un fiasco. Una vez, durante un recreo, contó un enigma lógico bastante rebuscado. Yo no di con la respuesta."}, {"type": "p", "text": "—¡Vamos! —se rio—. ¿Qué le pasó a nuestro genio?"}, {"type": "p", "text": "—Dejalo en paz —dijo Watson."}, {"type": "p", "text": "—¿Cómo? ¿El genio necesita de su secretario para protegerlo?"}, {"type": "p", "text": "No sé bien por qué esa frase me irritó de manera extraordinaria."}]$lira$::jsonb,
  787
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'el-camino-de-sherlock',
  27,
  'Parte 28',
  $lira$[{"type": "p", "text": "—¿Por qué no te vas a la mierda? —le dije. A nuestro alrededor se hizo un extraño silencio. Era la primera ve:z que yo decía una cosa así. Siempre me vanaglorié de mi capacidad para argumentar fríamente en una discusión y antici par las posiciones de los otros. Jamás exponía mis debilidades con una reacción intempestiva. Pero también estaba perdiendo eso. Con los profesores la situación no era muy distinta. Si yo hacía una pregunta muy espe cífica sobre alguna cuestión a la que acababan de referirse, solían reaccionar a la defensiva, como si los estuviera cuestionando. En una oportunidad me saqué un cinco en una prueba de Matemática. Era algo que nunca antes había sucedido. Cuando me la devolvió, claramente incómoda, la profeso ra me ofreció la posibilidad de discutir más tarde los puntos en los que me había equivocado. Watson recibió en silencio su propia prueba. Se había sacado un siete."}, {"type": "p", "text": "—Se equivocó al corregir —sostuvo—. Seguro."}, {"type": "p", "text": "Mi madre fue previsible."}, {"type": "p", "text": "—¿Qué es lo que buscás? —dijo al ver la calificación—. ¿Parecer una persona mediocre? En esa época decidí que quería dejar de ser yo. Durante varios días me planteé este problema de la forma más clara y racional posible: ¿cómo podía borrar mi pasado? ¿Qué habría hecho Holmes si no hubiese querido parecer Holmes? Esa respuesta era fácil: él se habría disfrazado. Era capaz de transformarse en un mendigo o una anciana en un instante y nadie podía reco nocerlo."}, {"type": "p", "text": "Por supuesto, yo no iba a disfrazarme. Pero con el correr de los días llegué a la conclusión de que había otras formas de no ser reconocido. Para empezar, tenía que cambiar de colegio, tenía que introdu cirme en un medio donde fuera uno más, igual que los otros. Diluir mi personalidad. Estábamos al final de segundo año y pensé que podía empezar el siguiente ciclo lectivo en otro lado. Tras una breve investigación, localicé un colegio no muy lejos de casa que parecía bastante bueno. Incluso mejor que el anterior. Convencer a mis padres no fue difícil: les dije que allí ofrecían una especialización científica para los últimos cursos y que me presentaría mayores desafíos que la institución en la que estaba. Aceptaron. Había, sin embargo, algo que me detenía: Watson. Dejar a mi único amigo me parecía un precio demasiado alto."}, {"type": "p", "text": "Durante dos días di vueltas en torno a mi futura escuela buscando información. Luego le propuse la idea: cambiarnos juntos. Le di dos argumentos de peso para convencerlo: que la nueva tenía un campo de deportes muy superior (ha sido siempre un fanático del fútbol) y que las chicas eran más lindas (había notado que este asunto le estaba interesando mucho). Eran buenos argumentos, pero igual noté que dudaba. Insistí, casi rogué:"}, {"type": "p", "text": "—No me vaya a fallar, Watson —dije poniendo una mano en su brazo—. Usted nunca me ha fallado."}, {"type": "p", "text": "—¿Eso es una cita?"}, {"type": "p", "text": "—Sí, lo dice en La aventura del detective agoniU/.nte. Pero en este caso es cierto. Creo que se conmovió. Era probablemente la primera vez que yo le expresaba afecto de manera explícita. Terminó aceptando. Ahora que han pasado dos años pienso que en líneas generales fue una buena decisión. En mi nueva escuela no tuve mayores problemas para pasar inadvertido. A los cambios naturales que se habían producido en mi cuerpo desde el concurso sumé unos anteojos que acababan de recetarme por una leve miopía y un nuevo corte de pelo."}, {"type": "p", "text": "Hubo algunos que me preguntaron sobre mi corta edad. Les expliqué que estaba adelantado porque había viajado mucho con mi padre, a quien su trabajo llevaba de un lado a otro, y por eso había dado varios cursos libres. Era una explicación confusa y vagamente incoherente que sin embargo pareció resultar satisfactoria. Pero un día noté que uno de mis flamantes compañeros me observaba largamente antes de acercarse."}, {"type": "p", "text": "—¿Vos no estuviste en la televisión?-me preguntó."}]$lira$::jsonb,
  646
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'el-camino-de-sherlock',
  28,
  'Parte 29',
  $lira$[{"type": "p", "text": "—¿Y o? —sonreí aunque estaba aterra do—. No, ya me lo dijeron otras veces: creo que me parezco mucho a alguien conocido. Pero no. Eso pareció zanjar el asunto. Desde ese momento he sido un alumno bueno, uno de los seis o siete mejores del curso, pero procuré no destacar demasiado nunca. No intento lucirme con los traba jos y en las pruebas evito siempre entregar primero. Creo que las cosas me van mejor desde que parezco uno más. No es que me haya integrado completa mente al resto de la clase, pero al menos tengo una relación bastante normal con mis compañeros e incluso participé en algunas salidas grupales que no estuvieron nada mal. Me propuse no hacer nada que me diferenciase de los demás. Por supuesto, sé que mi comportamiento es una nueva desilusión para mi madre. Hace poco me sugirió que me anotase en las Olimpíadas de Matemática. Yo estaba mirando tele visión y me limité a riegar con la cabeza."}, {"type": "p", "text": "—¿Por qué no?"}, {"type": "p", "text": "—Porque no me interesa. Y porque no soy tan bueno en Matemática. Resopló como si hubiese dicho una estu pidez."}, {"type": "p", "text": "—¡Por favor!"}, {"type": "p", "text": "Sé que ella todavía espera. Piensa que es posible que un día exhiba al mundo la genialidad que estoy ocultando. Pero yo no creo que aún tenga eso tan especial. Si es que algún día lo tuve. Hace poco, leyendo un libro de biografías de grandes hombres (que, por supuesto, compró mamá) encontré una mención al pasar a alguien que nunca había oído nombrar: Wtlliam Sidis. La curiosidad me llevó a rastrearlo a través de internet hasta que di con su historia. Me resultó aterradora. Sidis fue una de las personas más inteligen tes del mundo. Tenía supuestamente un cociente de entre 250 y 300. Antes de los cuatro años había aprendido latín y griego. A los ocho terminó la secundaria, pero recién a los once logró que acepta ran su ingreso en la Universidad de Harvard. Ese mismo año dio una conferencia sobre la cuarta dimensión frente a numerosos matemáticos. Ya entonces era una celebridad. Se graduó con honores a los dieciséis y obtuvo un cargo de profesor. Se esperaba que fuera uno de los más grandes mate máticos del siglo, un hombre que expandiera los límites del conocimiento. La prensa lo acosó incansablemente en busca de entrevistas: querían saber qué pensaba, cómo vivía. No lo soportó. Tras dejar su cargo, desapareció. Poco después se supo que trabajaba como oficinista. Huyó varias veces, pero los periodistas lo encontraban siempre. A uno de ellos llegó a decirle que la mera, visión de una fórmula matemática lo enfermaba. Se dedicó a coleccionar pasajes de tranvía y escribió un aburridísimo libro sobre ese tema. Pasajes de tranvía: parece difícil de creer. Pero dicen que juntó más de dos mil. Lo estuve pensando. Quizás el tipo perdió lo que tenía: sen cillamente, se le agotó."}, {"type": "p", "text": "Estaba leyendo las últimas novedades sobre Armando Rosales en la tarde del sábado cuando mamá me dijo que Arturo acababa de tocar el timbre y subía. Me alegró oírlo."}, {"type": "p", "text": "—Qué suerte que viniste, Watson —dije cuando abrí la puerta—. Necesito que hagas de Watson."}, {"type": "p", "text": "Me miró sin entender."}, {"type": "p", "text": "—¿O sea?"}, {"type": "p", "text": "—Que discutamos algunas ideas que tengo sobre la serie de muertes de Belgrano. Como hacen Holmes y Watson. Frunció el entrecejo."}, {"type": "p", "text": "—¿No hace de tonto Watson en esos casos?"}, {"type": "p", "text": "—¿Tonto? No- me parece. \"Cabe que usted mismo no sea luminoso, Watson, pero sin duda es un buen conductor de luz —cité—. Hay personas que sin ser genios poseen un notable poder de estímulo''. El sabueso de los Baskerville."}, {"type": "p", "text": "—No sé si eso me sonó muy bien. No importa. ¿Cuáles son tus ideas? Nos habíamos sentado en mi habitación frente a la mesa cubierta por los artículos que venía recortando."}, {"type": "p", "text": "—Todo esto no cierra. No es posible que Rosales sea el culpable de todos los casos. Mi idea es que no hay un criminal sino dos y que el que atraparon es el más inofensivo. El peligroso es el que aún está libre."}, {"type": "p", "text": "—Pero si todo concuerda. Es evidente que es él."}, {"type": "p", "text": "-((No hay nada tan engañoso como un hecho evidente\". Un caso de identidad."}, {"type": "p", "text": "—¿Tu argumento es una cita?"}, {"type": "p", "text": "—No. Escuchá, Watson. Tenemos cinco casos: el de la estación de tren, el de la confitería y las tres muertes, Huang Mei, María Luisa Reyes y Lucía Bernárdez. El comportamiento del asesino manifiesta dos patrones completamente diferentes. No coincide."}, {"type": "p", "text": "—¿Por qué?"}]$lira$::jsonb,
  741
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'el-camino-de-sherlock',
  29,
  'Parte 30',
  $lira$[{"type": "p", "text": "—En los dos primeros casos parece completamente descuidado. Se deja ver la cara por varios testigos, se expone a que lo detengan. En la estación dispara contra un vagón de tren vacío: no hay un blanco. En la confitería abre fuego con~ra una ventana, con el alto riesgo de que las balas'no lleguen a darle a nadie. No parece actuar según un plan coherente. En los tres asesinatos, en cambio, elige lugares y horarios en que corre pocos riesgos. Quienes llegan a cruzárselo no pueden describirlo porque lleva casco. Sus disparos son certeros. Es mucho más cauto y astuto."}, {"type": "p", "text": "—Pero hay varios elementos que unen los casos: la moto, el impermeable, el tipo de arma, las bolsas del supermercado ..."}, {"type": "p", "text": "—Justamente. Demasiados elementos. ¿Qué asesino se olvida un guante en la escena de un crimen, deja huellas de la moto en otro y se hace notar por el ruido? Creo que lo que en realidad hizo fue plantar pistas a propósito. En el caso de Reyes, no había motivo alguno para que entrara con la moto en el pasaje. Sólo se explica si quería asegurarse de que alguien lo oyera. Lo de la bolsa del supermercado es evidente: ¿por qué iba a ir Lucía Bernárdez hasta El Amanecer a comprar un paquete de arroz si tiene varios negocios a la vuelta de su casa? Es obvio que el asesino lo colocó ahí para estar seguro de que nadie dejaría de relacionar los crímenes."}, {"type": "p", "text": "—¿Te parece?"}, {"type": "p", "text": "Watson no se veía nada convencido. Pensé que no estaba reaccionando como el Watson literario. Yo tenía que exponer mejor mis argumentos."}, {"type": "p", "text": "—Esta es mi idea. El tipo se entera de los dos primeros casos: hay un loco que disparó sin ningún objetivo en la estación de tren y en el bar. Sabe que anda en moto, que lleva un impermeable oscuro, que usa una pistola .380. Decide cometer una serie de asesinatos respetando esas característi cas. Piensa que en algún momento el loco va a caer y se los van a adjudicar todos. El loco es Rosales. Cuando cae, vuelve a mostrarse tan descuidado como en los primeros casos: lleva su moto a la ferretería, va armado, se involucra innecesaria mente en una pelea ... Ese no puede ser el hombre que planeó con cuidado los tres crímenes. La poli cía, sin embargo, está muy contenta por la deten ción. Tienen un culpable. Lá gente se tranquilizó y nadie quiere seguir haciendo preguntas. No lo van a buscar más."}, {"type": "p", "text": "—Es una teoría interesante —dijo Watson—. Pero tengo una objeción."}, {"type": "p", "text": "—¿Cuál?"}, {"type": "p", "text": "—Tu asesino es un ser astuto y racional. ¿Por qué mataría a tres mujeres que no tienen ninguna relación entre sí? Suspiré."}, {"type": "p", "text": "—Sí, ese es el problema. Todavía no encontré el motivo. Quizás es cierto que todas sabían algo. Quizá fueron testigos de un hecho que lo involucra. Pero no lo sé. Y, no sabiendo eso, nadie lo va a atrapar. A menos que siga matando, lo cual es improba ble, ya que ahora que Rosales está preso no tiene cobertura. Pero estoy seguro de que hay otro."}, {"type": "p", "text": "—La idea no está mal, Sherlock, pero te falta mucho para poder decir \"Elemental\". Odio cuando Watson tiene tanta razón. Desde chico, varias veces escuché a mi madre expresar una idea que no sé de dónde sacó. Puede formularla de distintas maneras, pero el concepto básico es el mismo: que hay una gran discre pancia entre mi desarrollo intelectual y mi desarrollo emocional. Creo que en mi primera infancia ella pretendía explicar de ese modo por qué en ciertos momentos yo me mostraba como un chico brillante e inusualmente maduro y en otros armaba unos berrinches espantosos, como si fuera un bebé. Una vez que crecí siguió diciendo esa frase, pero ahora tiene otro objetivo: justificar que mi vida social es casi inexistente. Ella cree que no tengo más amigos porque mis compañeros de colegio no están a mi altura intelectual y mi supuesta inmadurez emocional me impide buscar otro tipo de relaciones."}, {"type": "p", "text": "Yo no estoy de acuerdo. Creo que sencilla mente no soy una persona muy sociable. Lo tengo a Watson, y hay un par de compañeros que me caen bien. No necesito más. No soy, por cierto, el tipo de persona que se divierte mucho en fiestas o parques de diversiones. Creo que no sé cómo comportarme en esos momentos. Prefiero quedarme en casa con un buen libro o frente a la com putadora."}, {"type": "p", "text": "Está además el tema de las chicas. A mí por ahora no me interesan. Para ser honesto, debería decir que yo tampoco les intereso a ellas en lo más mínimo. Es normal. Aunque crecí bastante en el último tiempo, a mis catorce años sigo teniendo aspecto un poco infantil. En cambio mis compañeras, que tienen dieciséis, ya parecen mujeres y, debería decir, unas niujeres bastante impresionantes. Nadie podría esperar que se fijen en mí."}]$lira$::jsonb,
  814
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'el-camino-de-sherlock',
  30,
  'Parte 31',
  $lira$[{"type": "p", "text": "Pero no me importa, realmente. No me siento en absoluto inclinado hacia el romanticismo. En ese aspecto me identifico con Sherlock Holmes. \"El amor es un estado emotivo, y todo lo emocional resulta opuesto al razonar frío y sereno, que yo coloco por encima de todas las cosas\" (Estudio en escarlata). Eso, por supuesto, no me impide admirar a las mujeres en un plano, digamos, estético. El propio Holmes sostenía que Irene Adler era \"la cosa más bonita que se ha visto bajo un sombrero en este planeta\" (Escándalo en Bohemia). Yo podría decir lo mismo de Violeta, obviando por supuesto la parte del sombrero. • Y si vengo recordando a Violeta es por la noticia del diario, que me hizo volver al pasado, más específicamente al momento en que me porté tan mal con Ignacio y ella me miró de esa manera que nunca pude olvidar. Es una espina que tengo clavada desde entonces. Por eso, cuando vi en el artículo que ella iba a estar en la exhibición de proyectos premiados, pensé que podría darme una vuelta por el lugar y explicarle que en aquella oportunidad no fue mi intención perjudicar al chico de los poemas homéricos. Y tal vez ella podría ayudarme a eliminarla culpa que me per sigue desde ese día."}, {"type": "p", "text": "Con ese objetivo, el martes pasado salí de mi casa a las tres de la tarde. En el momento en que llegué al museo, sin embargo, me sentía tan agitado que estuve a punto de dar media vuelta y olvidarme del asunto. Durante cinco minutos debatí con las fuerzas en mi interior que me suge rían volver a casa lo antes posible. Al fln me obli gué a entrar y encaré hacia el espacio que habían destinado a la muestra escolar. Se exhibían cinco o seis proyectos, pero no tuve problemas en iden tificar el suyo: un gigantesco hormiguero, confec cionado en acrílico transparente, que permitía ver el movimiento de las hormigas en su interior. Sin embargo, ella no estaba a la vista. Había otras dos chicas explicando los detalles a un grupo de personas que se habían detenido. Evidentemente eran sus compañeras. Pensé que habrían decidido tur narse y no era este el horario de Violeta. A fin de cuentas, había venido para nada. Enfilaba hacia la puerta, decidido a irme, cuando la vi. Salía del baño conversando con otra chica y durante unos segundos pude mirarla sin que lo advirtiera. Llevaba jeans, botas negras y un suéter rojo ceñido al cuerpo. La amiga debió contarle algo gracioso, porque soltó una carcajada cristalina mientras echaba la cabeza hacia atrás, haciendo revolotear sus rizos oscuros. Era la misma y a la vez era otra. Otra mucho mayor. Me impactó tanto su cambio que desvié la vista y seguí mi camino hacia la salida. Pero entonces ella me vio. Abrió los brazos y sonrió generosamente."}, {"type": "p", "text": "—¡No lo puedo creer! ¡Sherlock! Me acerqué obligándome a sonreír."}, {"type": "p", "text": "—Hola, Violeta. Pensé que no estabas."}, {"type": "p", "text": "—¿V iniste a verme? Qué dulce. ¿Y cómo estás?"}, {"type": "p", "text": "—Muy bien. ¿Y vos?"}, {"type": "p", "text": "—Bien. ¿Y qué tal todo?"}, {"type": "p", "text": "Pensé que podíamos seguir así eternamente y decidí ser directo."}, {"type": "p", "text": "—Quería hablarte de un asunto del pasado."}, {"type": "p", "text": "Levantó las cejas intrigada. Empecé a hacer un resumen lo más claro posible sobre el episodio de Ignacio, Ayax el Menor y la pregunta que lo descalificó, pero me interrumpió."}, {"type": "p", "text": "—No entiendo nada, Sherlock. ¿De qué hablás?"}, {"type": "p", "text": "Volví a la anécdota, centrándome ahora en mi gesto equívoco hacia Ignacio y esa mirada que ella me había dirigido, clara muestra de que pensaba muy mal de mí. Me interrumpió otra vez, riéndose. No sé si quería ayudarme a olvidar o jamás le había dado importancia a ese asunto."}, {"type": "p", "text": "—No recuerdo nada de lo que contás y te aseguro que nunca pensé mal de vos —dijo—. Al contrario. Todo eso es historia antigua, hable mos de otra cosa. Justamente hace unos días me acordé de vos."}, {"type": "p", "text": "—¿De mí? ¿Por qué?"}, {"type": "p", "text": "—Por ese asunto tan raro de los crímenes en Belgrano. Pensé: seguramente Sherlock, que es un genio, tiene una idea sobre estas muertes. Y justo entonces detuvieron al asesino."}, {"type": "p", "text": "—Yo tengo mis dudas."}, {"type": "p", "text": "Pareció muy interesada."}, {"type": "p", "text": "—¿Qué, no es el asesino?"}, {"type": "p", "text": "—Puede que sea el responsable de alguno de los episodios, pero estoy convencido de que el verdadero asesino es otro."}, {"type": "p", "text": "—¿De verdad? —sonrió, abriendo gran des los ojos—. ¿Quién?"}]$lira$::jsonb,
  728
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'el-camino-de-sherlock',
  31,
  'Parte 32',
  $lira$[{"type": "p", "text": "—Todavía no sé. Pero no te olvides: hay otro asesino y tarde o temprano va a caer. Hablamos un poco más de nuestros conocidos en común, a quienes no habíamos vuelto a ver, y de otros temas intrascendentes. Después le dije que tenía que irme. Violeta me invitó a quedarme otro rato y conocer a sus amigas, pero pretexté un compromiso urgente. No aguantaba más las náuseas. Cuando salí, me apoyé en un muro de la calle y tomé aire lenta mente. \"No te olvides: hay otro asesino y tarde o temprano va a caer\". Lo había dicho yo. Dios, qué estúpido. Qué increíblemente estúpido. entonces sucedió algo. Fue como si cien kilos de plomo cayeran sobre mi orgullo: apareció el arma. &taba hojeando el diario rápidamente antes de ir al colegio cuando vi el titular: \"Encontraron la pistola asesina'. Corté el artículo sin oír las protes tas de mi padre, que aún no lo había tocado, y salí. A medida que iba leyendo, mis pasos se hicieron más y más lentos. &taba todo ahí, hasµ el último detalle. Me senté en un parque, cerré los ojos un momento y pensé que hubiera sido bueno pasar la noticia por alto esa mañana, tener al menos un día más sin enfrentarme a mi estupidez. El arma había aparecido entre los objetos personales de Rosales. Fue Emilio Serrano, el dueño del departamento en el que vivía, quien dio el alerta. Según le explicó a la policía, apenas tomó posesión de la propiedad se dispuso a ponerla en condiciones para alquilarla otra vez. Un familiar lejano de Rosales se presentó a retirar la ropa y los muebles que habían quedado. Poca cosa y en mal estado. Cuando el hombre estaba por irse, Serrano recordó la existencia de la baule ra y lo invitó a bajar, para ver si había quedado algo allí que mereciese ser retirado. Las bauleras de ese ediflcio están ubicadas en el subsuelo, junto a las cocheras. Ahí cada unidad tiene asignado un cubículo enrejado, donde se guardan muebles en desuso y otros objetos. Las puertas están aseguradas con candados. Dice Serrano que probó todas las llaves que encontró, pero ninguna funcionaba: Rosales debió llevársela con él. Entonces decidió romper el candado con una sierra. Adentro solo había una silla rota, dos valijas polvorientas y algunas cajas con cosas de escaso valor: vajilla descascarada, viejos discos, adornos pasados de moda. El familiar de Rosales le dijo que tirara todo y eso se disponía a hacer cuando levantó una caja de zapatos y el peso llamó su atención. Adentro estaba el arma. Todo eso había sucedido tres días atrás, pero la polida había mantenido el asunto en silencio mientras se hacían las pericias. Ya se conocían los resultados y no había dudas: era la pistola usada para matar a María Luisa Reyes y a Lucía Bernárdez;. Rosales era el único culpable. Mi teoría se caía a pedazos y mi ánimo también. Cuando se lo conté, Watson me miró con compasión."}, {"type": "p", "text": "—Cualquiera puede equivocarse —dijo."}, {"type": "p", "text": "—No lo puedo creer. Nada de esto tiene sentido. ¿Cómo pude sacar conclusiones tan erradas?"}, {"type": "p", "text": "—No te lo tomes así —insistió—. Es solo un error."}, {"type": "p", "text": "Pero no había nada que ese día pudiera consolarme."}, {"type": "p", "text": "—Supongo que me creí mucho más Holmes de lo que soy en realidad —le dije—. Soy un fiasco, Watson, un fiasco. Durante días, me torturó el recuerdo de mi estúpida frase: \"No te olvides: hay otro asesino y tarde o temprano va a caer\". na vez le oí decir a mi madre que se arrepentía de haberme impulsado a participar en el concurso televisivo. Estaba en la sala con una amiga y no sabía que yo escuchaba desde la cocina, de lo contrario supongo que no lo hubiera dicho. Le explicó que esa experiencia había hecho que yo ocultara mis talentos y me recluyera en un excesivo interés por cuestiones un tanto macabras. O sea, las historias de crímenes. Dijo también que todavía tenía que recuperar mi camino. Y que cuando lo hiciera iba a ser \"alguien1 Porque yo estaba destinado a ser \"alguien\". Creo que no estoy de acuerdo. En realidad, yo todavía no sé exactamente cuál es mi camino, si es que existe uno."}]$lira$::jsonb,
  703
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'el-camino-de-sherlock',
  32,
  'Parte 33',
  $lira$[{"type": "p", "text": "Volví a leer sobre ese hombre, William Sidis. Contra lo que había pensado, al parecer los últimos años de su corta vida (murió a los cuarenta y seis, por una hemorragia cerebral) fueron bastante activos. No en la línea que se esperaba, claro. Escribió varios libros y artículos, en su mayoría con seudónimo. En uno de ellos, sobre la evolu ción del cosmos, anticipó conceptos como la idea de los agujeros negros, que no iban a oírse hasta mucho después. En otros habló sobre el continente perdido Atlantis, los orígenes de Norteamérica, la historia de la ciudad de Boston y por supuesto su gran hobby, los boletos de tranvía. Al principio ese asunto de los boletos me dio un poco de tristeza: me imaginaba a este Sidis, uno de los hombres más inteligentes dd mundo, recorriendo las calles de la ciudad con la mirada en d suelo. De pronto vería un boleto entre la basura, o junto a las hojas caídas de un árbol, y lo levantaría para guardarlo con delicadeza en una bolsa, cuidando que no se arru gara mucho. En su casa seguramente los clasificaría: grandes pilas separadas por año, por serie, por color. Todo bastante patético. '~ún no se ha explotado este tipo de colección, pero no hay ninguna razón por la que no pueda ser tan interesante como otros hobbies, tal como coleccionar estampillas, monedas, medallas, billetes y otros objetos —escribió en su libro—. Alguna gente se ha mostrado interesada incluso en coleccio nar cajas de fósforos, ¿por qué no boletos?\". Después lo pensé.y me dije: a fin de cuentas ¿por qué no boletos? Quizá no fue tan mala su vida, recorriendo las calles por las mañanas y mirando el cielo por las noches, pensando a ratos en los boletos, a ratos en el futuro del cosmos, en esa inmensidad frente a la cual ningún hombre es \"alguien\", porque la humanidad entera es tan pequeña, tan insignificante, que casi es nada. Quizás el tipo nunca perdió el brillo de su mente. Quizá sólo eligió escaparse de lo que los demás esperaban de él. Cuando necesita relajarse en medio de un problema, Sherlock.Hohnes toca su violín Stradivarius o fuma una pipa. Yo no hago ninguna de las dos cosas. A veces miro la foto de V838 Monocerotis. Y también descubrí que una ducha con agua bien caliente me despeja el cerebro. Llevaba veinticinco minutos bajo el chorro hirviendo (y mi madre ya había golpeado dos veces para preguntar si me sentía bien) cuando se disipó la niebla que venía oscureciendo mis ideas. Me di cuenta de que hasta ese momento mi pen samiento había tomado un camino equivocado: un camino pensado por otro para hacerme trope zar. Pero ahora, en medio del vapor de la ducha, veía todo perfectamente claro. Cerré las canillas, me sequé y vestí a toda velocidad y salí de casa. Veinte minutos más tarde estaba frente al edificio donde había vivido Rosales. Esperé pacientemente hasta que salió una persona sin fijarse si la puerta cerraba y entré. No me costó mucho encontrar la escalera que bajaba al subsue lo. A un lado estaban las cocheras y al otro había una puerta. La abrí, confieso, un poco asustado: temía encontrarme a alguien. Pero no había nadie. Al fondo de un pasillo vi las bauleras. Era una serie de cubículos enrejados de distinto tamaño. Cada uno llevaba un pequeño cartel que indicaba a qué departamento pertenecía. Caminé hasta llegar al que decía \"1B\". Tenía un candado reluciente, el que el señor Serrano había colocado tras romper el viejo. Adentro de la baulera, por supuesto, no había nada. Pero no era el contenido lo que importaba. Lo verdaderamente importante era que yo estaba ahí. Y eso resolvía todo. No me pareció que las diez de la mañana de un domingo fuese un horario inapropiado, pero el tono de voz de Watson al otro lado de la línea sugería lo contrario."}, {"type": "p", "text": "—¿Qué pasa?"}, {"type": "p", "text": "Yo le había pedido a su madre que lo despertara porque se trataba de un asunto urgente."}, {"type": "p", "text": "—Necesito que vengas ahora a hacer de Watson. Lo tengo todo resuelto."}, {"type": "p", "text": "—Escuchame, Fran —empezó, lo cual fue una clara muestra de su fastidio, ya que solo me llamaba por mi nombre en el colegio—, son solo las diez. ¿Esto no puede esperar? Digamos, ¿a las tres de la tarde?"}, {"type": "p", "text": "—Podemos negociar. Las doce."}, {"type": "p", "text": "—Las dos."}, {"type": "p", "text": "—La una. Y hay pizza."}, {"type": "p", "text": "—Está bien —se rindi&—. A la una voy. Cuando llegó yo terminaba de redactar algunas notas sobre d caso. Me miró con escepticismo."}, {"type": "p", "text": "—De modo que está ... ¿resuelto? Mientras lo decía levantó sólo una ceja, una gracia que había perfeccionado recientemente, sospecho que tras muchas horas de práctica frente al espejo."}, {"type": "p", "text": "—Bueno, casi resuelto."}, {"type": "p", "text": "Suspiró mientras se dejaba caer sobre mi cama."}, {"type": "p", "text": "—Escuchemos."}]$lira$::jsonb,
  798
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'el-camino-de-sherlock',
  33,
  'Parte 34',
  $lira$[{"type": "p", "text": "—Vamos a dejar por el momento el asunto del arma de lado: eso va a llegar después. Creo que todo este caso se trata, fundamentalmente, de un juego de apariencias. Ya vimos que Rosales no puede ser culpable de las tres muertes. Eso es lo que quiere el asesino que pensemos: que hay un loco que comete una serie de crímenes, que anda en moto, que lleva impermeable. Que no existe un motivo para esos asesinatos, o, si existe, es algo absurdo, conectado a la presencia de las mujeres en el supermercado El Amanecer."}, {"type": "p", "text": "—Sí, hasta ahí habíamos llegado. ¿Encontraste d motivo?"}, {"type": "p", "text": "—No te apures. Lo que hizo el asesino fue ponernos un velo en los ojos, a través del cual no podíamos ver claramente. O mejor: lo veíamos sólo con su lógica. Lo que hay que hacer es que brar esa lógica, observar el asunto desde otro punto de vista. ¿Oíste hablar del pensamiento lateral?"}, {"type": "p", "text": "—Sherlock, tengo mucho sueño. ¿Podemos ceñirnos al caso?"}, {"type": "p", "text": "—Bueno. Me propuse descartar todas sus premisas. Me dije lo siguiente: el criminal no es un loco. Las pistas que unen los casos no son ciertas. Y el motivo existe."}, {"type": "p", "text": "—¿Y cuál es? —preguntó Watson, creo que un poco exasperado."}, {"type": "p", "text": "—El problema era que no parecía posible encontrar un motivo para las tres muertes. Ese es el corazón del caso. Y la respuesta es que única mente existe el motivo en una de ellas. Lo demás, mi querido Watson, forma parte del velo que tejió el asesino. Las otras dos muertes solo fueron para disfrazar su objetivo."}, {"type": "p", "text": "Watson se incorporó en la cama."}, {"type": "p", "text": "—¿Solo una? ¿Cuál?"}, {"type": "p", "text": "—Aposté por la tercera y no me equivoqué. Me puse en el lugar del asesino. Pensé: quiero cometer un crimen, pero temo ser descubieno por mi relación con la víctima. Me entero de los dos incidentes de Rosales: la estación de tren y la con fitería. Necesito que eso se convierta en una serie de ataques cometidos por un demente. Por eso, voy a dejar mi objetivo para el final, para cuando todos estén convencidos de que se trata de un loco y de que no hay un motivo racional. ¿T e acordás cómo llegó a unir la policía los dos primeros incidentes con las muertes?"}, {"type": "p", "text": "—Por una llamada anónima."}, {"type": "p", "text": "—¿Y quién habrá hecho la llamada?"}, {"type": "p", "text": "—¿El asesino?"}, {"type": "p", "text": "—Exactamente. La policía estaba tardando en llegar a la conclusión que él quería y les dio una mano. También por eso fue haciendo las pis tas cada vez más burdas. Fijate: en el caso de Huang Mei, nadie oyó ninguna moto. Quizá no la usó, o quizá pasó inadvertida. En el segundo caso quiso asegurarse: por si no lo oían, dejó el guante. Y en el tercero, huellas. Y la bolsa del supermercado. Ya se estaba poniendo un poco grotesco, a mi gusto, pero se ve que dudaba de la viveza de los investigadores."}, {"type": "p", "text": "—¿Y cómo es el asunto del motivo?"}, {"type": "p", "text": "—A eso iba. El tercer caso, en medio de la histeria desatada por el supuesto demente, fue el menos investigado. Pero resulta que el motivo era bastante claro: dinero. Lucía Bernárdez había heredado muchísimo dinero de su padre. Su madre había fallecido cuando ella era chica y no tenía hermanos. Pero tenía un novio. Y si llegaba a casarse ..."}, {"type": "p", "text": "—Se convertía en su heredero."}, {"type": "p", "text": "—Así es —tomé un par de revistas que tenía sobre el escritorio—. Compré esta basura: te recomiendo que nunca leas este tipo de revistas, Watson, son malísimas. Bueno, aquí hicieron una nota con un par de amigas de la chica muena, donde cuentan que, más allá del novio, ellas eran el verdadero respaldo en la vida de Lucía, porque a la pobre no le quedaba ningún familiar, excepto ... un primo. Y en esta otra —pasé rápido las hojas de la segunda revista- hicieron la cobertura del entierro. Lamentablemente no los dejaron sacar fotos, pero aquí cuentan que uno de los que llevaron el féretro era su primo, el ex jugador de rugby Marcelo Legui7.amón."}, {"type": "p", "text": "—Es decir, tu sospechoso."}, {"type": "p", "text": "—Exactamente."}, {"type": "p", "text": "—Entonces... —Watson levantó su ceja derecha—, tenemos un ex jugador de rugby, un tipo de clase media y seguramente una buena educación que. .. ¿de pronto mata no solo a su prima sino a otras dos personas para heredar? ¿No es improbable?"}, {"type": "p", "text": "—Puede ser, pero no es imposible. '~gunos árboles, Watson, crecen derechos hasta cierta altura y de pronto desarrollan cualquier extraña deformidad. Lo mismo sucede a menudo con las personas'>. La aventura de la casa vacía. Watson resopló y puso los ojos en blanco. Me apuré a seguir."}, {"type": "p", "text": "—La verdad es que el tipo tenía buenos motivos. Estuve investigando. ¿Sabés que existe un sitio en internet donde podés encargar un informe sobre la situación crediticia de cualquier persona? Alcanza con poner un número de tarje ta de crédito."}, {"type": "p", "text": "—¿Y vos tenés tarjeta de crédito?"}]$lira$::jsonb,
  809
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'el-camino-de-sherlock',
  34,
  'Parte 35',
  $lira$[{"type": "p", "text": "—Usé la de mi mamá .-bajé la voz—. Ella piensa que fue para comprar un libro. La cuestión es que este hombre tiene muchas deudas. Dejó de pagar un crédito, tuvo un par de juicios .y lo declararon insolvente. Estaba desesperado por obtener dinero. Planeó matar a su prima, pero tenía miedo de que lo arraparan. Entonces oyó hablar de los dos primeros episodios y armó la historia."}, {"type": "p", "text": "—Todo muy bien, Sherlock, ¿y la pistola?"}, {"type": "p", "text": "—Watson sonrió irónico—. ¿Le pidió a Rosales que se la guardara?"}, {"type": "p", "text": "—Llegamos al arma. Y aquí, querido Warson, nuevamente nuestras ideas habían tomado el camino equivocado: leímos que la pistola apareció entre los objetos personales de Rosales y dimos por sentado que fue él quien la puso ahí. Pero no. En realidad, es muy facil meterse eq. la casa y llegar hasta el sector de las bauleras. Yo pude hacerlo."}, {"type": "p", "text": "—Pero estaba cerrado con llave."}, {"type": "p", "text": "—Con candado. Y el dueño del departamento pensó que Rosales se había llevado la llave porque ninguna coincidía. Lo que sucedió fue que el asesino leyó, igual que nosotros, la noticia de la detención de Rosales y el allanamiento en su casa. Fue al lugar y descubrió las bauleras. Simplemente rompió el candado, dejó la caja con el arma y puso uno nuevo."}, {"type": "p", "text": "Watson sonrió."}, {"type": "p", "text": "—Brillante, Sherlock. Creo que ahora sí podés decirlo."}, {"type": "p", "text": "—¿Qué?"}, {"type": "p", "text": "—Ya sabés."}, {"type": "p", "text": "—Ah, sí. Elemental, mi querido Watson. Más tarde, cuando ya habíamos dado cuenta de la pizza, yo repasaba mis notas y Watson parecía estar durmiendo la siesta en mi cama, abrió súbitamente los ojos y me miró."}, {"type": "p", "text": "—¿Y ahora?"}, {"type": "p", "text": "—¿Ahora qué?"}, {"type": "p", "text": "—¿T enés pensado hacer algo con todo esto? Porque si fueras Holmes lo llamarías al inspector Lestrade o algún otro de Scotland Yard y lo cita rías en tu oficina para resolverle el caso. Pero dudo mucho que la Policía Federal quiera venir a oírlo en tu dormitorio."}, {"type": "p", "text": "—No, no pensaba recurrir a la policía. Más bien a la prensa. \"La prensa, Watson, es una institución valiosísima, si uno sabe cómo utilizar la\". La aventura de los seis napoleones. Me miró azorado."}, {"type": "p", "text": "—¿V as a hablar con un periodista? ¿V os?"}, {"type": "p", "text": "—Ni muerto. Jamás se me ocurriría una cosa semejante. Voy a escribir una carta al correo de lectores de un diario. Va a ser lo suficiente mente interesante como para asegurarme de que la publiquen."}, {"type": "p", "text": "Empecé a hacerlo en ese mismo momento. Primero expresé mi consternación ante el apre suramiento que parecían tener los investigadores por cerrar el caso adjudicando las muertes a Rosales con pruebas sumamente endebles. Luego argumenté que su perfil psicológico y los primeros incidentes no coincidían con la cuidadosa planifi cación de los tres asesinatos. Deslicé la posibilidad de que se hubieran plantado pistas falsas, sin entrar en muchos detalles. Y por último, señalé que en uno de los crímenes parecía haber un motivo bastante evidente que había sido poco investigado. Todo regado de jerga especialliada y palabras técnicas. Cuando llegué al momento de la firma dudé bastante. Finalmente escribí \"E M. García. Especialista en Criminología\" y se lo di a leer a Watson cuando despertó de su segunda siesta."}, {"type": "p", "text": "—¿Y esto?-preguntó al final levantando su ceja izquierda—. ¿E M. García?"}, {"type": "p", "text": "—Es una pequeña trampa —admití—. Federico Manuel García es un criminólogo muy conocido. Si piensan que es de él, hay más posibi lidades de que la publiquen."}, {"type": "p", "text": "—¿Y después?"}, {"type": "p", "text": "—Solo queda esperar."}, {"type": "p", "text": "—¿Esperar qué?"}, {"type": "p", "text": "—Que salga, que alguno de los investigadores la lea y que decida hacer algo."}, {"type": "p", "text": "—Eso es esperar mucho —dijo Watson y se dispuso a dormir su tercera siesta del día. En"}, {"type": "p", "text": "realidad, tuve que esperar muy poco. La carta fue publicada por el diario solo un día después, destacada con un recuadro que hacía imposible pasarla por alto. No habían tocado ni una coma. Lo que yo no había previsto era que bajo cada firma incluían la dirección de correo electrónico desde donde la carta había sido envia da. En mi caso, sherlock@telnet.com. Pensé que debí haberla mandado de otra casilla, pero ya era tarde para arrepentirme."}, {"type": "p", "text": "La sorpresa mayor vino horas después, cuando al revisar mi correo encontré dos res puestas. La primera no era muy interesante: una mujer me invitaba a participar de una iniciativa a favor de una justicia más ágil. Fue la segunda la .q ue me aceleró el pulso. En el asunto decía \"Sobre los crímenes de Belgrano\" y la firma era, para mi sorpresa, \"Miguel Ángel Flores, fiscal adjunto\"."}]$lira$::jsonb,
  742
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'el-camino-de-sherlock',
  35,
  'Parte 36',
  $lira$[{"type": "p", "text": "\"Estimado doctor García —empezaba—. He leído con detenimiento su carta publicada en el diario El Día. Ante la preocupación que manifiesta, quisiera aclararle que el caso aún no está cerrado. Seguimos investigando en diversas líneas, entre ellas la que involucra cienas motivaciones económicas, tal como usted sugiere. Sin embargo, nos resulta útil a nuestros propósitos que se crea que la pesquisa está cerrada, ya que nos da mayor libertad de acción. Por supuesto conozco sus ante cedentes en la materia y por su carta pude observar que ha tomado un gran interés en el caso. También creí entender que tiene más ideas sobre estos crímenes que las expresadas. Es por eso que me tomo el atrevimiento de pedirle que comparemos nuestras impresiones, si es que está actualmente en la capital. Yo podría visitarlo en su despacho o, si prefiere, lo invito a acercarse a mi oficina. Para mí será un gran gusto conocerlo personalmente, ya que he leído sus dos libros y escuchado algunas de sus con ferencias. A la espera de su respuesta, lo saludo con la mayor consideración\"."}, {"type": "p", "text": "La leí tantas veces que perdí la cuenta. Durante un buen rato estuve eufórico: uno de los fiscales a cargo del caso se había tomado muy en serio mis ideas. Claro que creía que yo era Federico Manuel García, lo cual complicaba las cosas. Empecé a pensar c.ómo salir de ese atolladero. Me moría por asistir a la cita y meter mi nariz en un caso verdadero, pero sabía que cuando el fiscal me viera se echaría todo a perder. Durante un buen rato pensé que no había solución posible. Pero al fin decidí contestarle: a fin de cuentas, no perdía nada. \"Estimado doctor Flores —decía el mensaje—: Le agradezco mucho la atención dedicada a mi carta. Si bien nada me gustaría más que discutir mis ideas del caso con usted, tengo la impresión de que me está confundiendo con otra persona. Mi nombre completo es Fernando Martín García y seguramente soy más joven de lo que imagina. Si aun así está interesado en realizar el encuentro, estoy a su entera disposición,,. Revisé el correo unas doce veces durante el día hasta que, por la tarde, recibí la respuesta. \"Estimado señor García: Tal como usted dice, lo confundí con otra persona. De todas formas, sus ideas me parecieron muy interesantes y no creo que su juventud sea un problema para nuestro encuentro,,. Al fl.nal, me invitaba a visitarlo en su despacho de Tribunales en el horario que me viniera mejor. Todavía intercambiamos un par de mensajes más: yo propuse que fuera al día siguiente, a las dos, y él aceptó. Agregó el número de su celular, para que lo ubicara al llegar en las oficinas de la fiscalía. Cuando finalmente la cita estuvo fijada salté de pura excita ción. Lo cual es algo muy poco frecuente en mí. Esa misma tarde se lo conté a Watson por teléfono. Escuchó en silencio mientras le explicaba todas las idas y venidas de mensajes."}, {"type": "p", "text": "—Nos encontramos mañana a las dos de la tarde. ¿Qué te parece?"}, {"type": "p", "text": "Claramente le parecía mal. Se notaba en la total ausencia de comentarios."}, {"type": "p", "text": "—Yo diría ... Norbury."}, {"type": "p", "text": "—¿Qué?"}, {"type": "p", "text": "—Norbury: eso fue lo que una vez me pediste que te dijera si te notaba demasi3:do confiado en tus facultades. Esto no es para vos, Sherlock. Acordare de que, por muy inteligente que seas, tenés catorce años. ¿No te das cuenta de que ese tipo no puede tomarte en serio?"}, {"type": "p", "text": "—¿Cuál es el problema? Si no quiere hablar conmigo, me voy. Pero no puedo despreciar esta invitación, Watson. ¿Cuándo voy a tener otra oportunidad de discutir un caso de verdad con uno de sus investigadores? Es emocionante."}, {"type": "p", "text": "—Pensá en lo siguiente: ese fiscal espera a una persona adulta, un probable especialista en Criminología, que se llama Fernando García y se va a encontrar con vos. Imaginate la cara que va a poner."}, {"type": "p", "text": "—Veremos. No pierdo nada con probar. ¿No será que estás celoso? Te juro que apenas vuelva te llamo y te cuento todo. Mi aparente seguridad, sin embargo, empezó a derrumbarse no bien llegué a la sede de las fiscalías. Era un edificio antiguo, bastante decaído y lleno de gente. Frente a los ascensores se había formado una cola, ya que sólo funciona ba uno de los cuatro. Mientras me ponía al final, conté doce personas: ocho hombres, todos con traje y corbata, y cuatro mujeres. Ningún chico. Recordé entonces que Flores me había pedido que le avisara por teléfono que ya estaba allí, pero cuando saqué mi celular para llamarlo la espina de la duda se me clavó en el estómago. Sentía que estaba a punto de protagonizar el papelón de mi vida. Lo mejor que podía hacer, me dije, era dar media vuelta y olvidarme del asunto. Salí otra vez a la calle. Estaba acalorado y ligeramente nauseo so. Me senté unos segundos en la escalinata y entonces me di cuenta de que esa era la verdadera derrota: dejar que el miedo me paralizara. Volví a sacar el celular y lo llamé."}, {"type": "p", "text": "—¿Doctor Flores? Soy Fernando García, ya estoy acá."}, {"type": "p", "text": "—Ah, muy bien —sonó algo desconcertado y supuse que había percibido la juventud en mi voz—. Estoy en el quinto piso, al final del pasillo, a la izquierda, Pero ... —pareció dudar y pensé que estaba por preguntarme la edad."}, {"type": "p", "text": "—¿Sí?"}]$lira$::jsonb,
  894
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'el-camino-de-sherlock',
  36,
  'Parte 37',
  $lira$[{"type": "p", "text": "—Que esto hoy es un caos: los ascensores no funcionan y encima están arreglando un des perfecto eléctrico en mi oficina. Tal vez sea mejor que me espere abajo y tomemos un café en la esquina. ¿Le parece bien?"}, {"type": "p", "text": "—Perfecto —dije, quizá con demasiado entusiasmo. Pensé que así me evitaba las miradas de los demás integrantes de la fiscalía."}, {"type": "p", "text": "—Entonces bajo enseguida . . ¿Cómo lo reconozco?"}, {"type": "p", "text": "—Tengo un libro en la mano —le dije—. La nueva criminología."}, {"type": "p", "text": "Supongo que lo había llevado para parecer un especialista. Ahora me haáa sentir un poco idiota. Lo identifiqué inmediatamente. Tenía el aspecto que había imaginado para un fiscal, con un traje formal y documentos en mano. Era bastante joven y estaba en buena forma: aunque había bajado por la escalera, no se lo notaba agitado. Recorrió el hall con la mirada, buscando. Creo que en un primer momento ni siquiera me registró, pero luego su mirada se clavó en mi libro y subió hacia mi cara. Vi que abría los ojos muy grandes mientras se acercaba."}, {"type": "p", "text": "—Bueno —dijo sonriendo—, esto sí que es una sorpresa. Dijiste que eras joven, pero ... nunca imaginé que tanto."}, {"type": "p", "text": "—Sí, ya sé —admití—. Todavía está a tiempo de irse."}, {"type": "p", "text": "Se rio. Parecía divertido con la situación."}, {"type": "p", "text": "—No, está bien. No creo que sea malo que tomemos un café. Además, estoy enorme mente intrigado. ¿Cómo pudo alguien de tu edad llegar a esas conclusiones? Pero mejor vayamos al bar y me contás."}, {"type": "p", "text": "—Soy un aficionado a la resolución de casos criminales desde hace tiempo —le dije mientras caminábamos—, llevo mucho leído. Apenas nos sentamos empezó abombar dearme a preguntas. Parecía realmente interesado. Le expliqué sintéticamente cómo había llegado a la conclusión de que Rosales no era el asesino y presumí un poco hablando sobre diferentes perfiles psicológicos criminales. Después entramos en la cuestión del motivo en el caso de Lucía Bernárdez."}, {"type": "p", "text": "—Sí, la cuestión económica es evidente: la chica tenía una considerable fortuna. Estuvimos investigando un poco por ese lado —hizo una pausa y sonrió—. ¿V os tenés algún sospechoso en vista?"}, {"type": "p", "text": "—Bueno, no quisiera apresurarme ~je—, pero hay un primo que podría reclamar la herencia. Marcelo Leguizamón. Él tiene un buen motivo."}, {"type": "p", "text": "—Exactamente —sonrió—, Leguizamón. De verdad me asombrás. Anduvimos tras sus pasos."}, {"type": "h", "text": "—¿Y?"}, {"type": "p", "text": "—Estuvo fuera del país un tiempo, lo cual podría excluirlo de alguno de los crímenes. Pero aún no lo interrogamos. No se puede proceder simplemente por corazonadas. Además, está el tema del arma en lo de Rosales."}, {"type": "p", "text": "—Sí —dije—, pero estaba en la baule ra, no en la casa. Cualquiera pudo ponerla ahí. Yo mismo estuve en el lugar: no es nada difícil acceder."}, {"type": "p", "text": "—¿Fuiste? —el fiscal se río abiertamente—. Estoy anonadado. Sos todo un investigador. Pero como te decía, no se puede avanzar sólo con sospechas y por el momento no tenemos ninguna prueba que comprometa a Leguizamón. Justamente, ahora voy a recoger unos documentos que pueden ayudarme."}, {"type": "p", "text": "Mientras pagábamos la consumición, Flores me pidió que fuera discreto sobre lo que habíamos hablado."}, {"type": "p", "text": "—Y también te pediría que no envíes más cartas a los diarios: no queremos alertar al even tual sospechoso."}, {"type": "p", "text": "—Por supuesto."}, {"type": "p", "text": "Salimos juntos ; la calle. Él levantó la mano para saludar a un hombre que acababa de salir de la fiscalía."}, {"type": "p", "text": "—Doctor —lo llamó el tipo mientras cruzaba—. No se vaya."}, {"type": "p", "text": "—¿Qué pasa, Claudio?"}, {"type": "p", "text": "—¿V uelve? Porque teníamos pendiente la reunión de la tarde por el caso Sabino."}, {"type": "p", "text": "—Mejor pasala para mañana. Ahora voy hasta lo de la chica Bernárdez, quiero recoger esas cartas. Pueden servirnos."}, {"type": "p", "text": "El tipo se alejó y Flores se quedó mirándo . lo, pensativo. Por un momento pareció olvidarse de mi presencia. Entonces giró y me sonrió."}, {"type": "p", "text": "—Bueno, ha sido un placer. ¿T e alcanzo a algún lado? Tengo el auto en el estacionamiento de enfrente."}, {"type": "p", "text": "Por supuesto, a mí no se me había escapado la mención a la casa de Bernárdez."}, {"type": "p", "text": "—¿V a para Belgrano?"}, {"type": "p", "text": "S <.y vos.;>"}, {"type": "p", "text": "- 1,"}, {"type": "p", "text": "—También, me puede dejar donde le quede cómodo."}, {"type": "p", "text": "—Perfecto entonces. Aunque ahora que lo pienso —me miró sonriendo mientras caminába mos—, ¿no querés acompañarme? Fue como si me hubiera leído el pensamiento."}, {"type": "p", "text": "—¿A lo de Bernárdez?"}, {"type": "p", "text": "—Sí. Quizá te guste ver la escena del crimen."}, {"type": "p", "text": "Era el mejor plan que alguien podía propo nerme."}, {"type": "p", "text": "—Me encantaría. Gracias."}, {"type": "p", "text": "Esperé en la entrada del estacionamien to mientras él pagaba y retiraba el auto. En ese momento un bip en mi celular me señaló que había un mensaje nuevo. Era de Watson y con tenía una sola palabra: \"¿Y?\". Le contesté a toda velocidad: \"Todo bien. Ahora voy a ver la escena del crimen\". Lo mandé antes de subir al coche."}, {"type": "p", "text": "Era extraño estar entrando a la casa que había visto decenas de veces en televisión. Flores sacó de su bolsillo un manojo de llaves que llevaba enganchado un papel con la palabra Bernárdez. Tuvo que probar tres antes de dar con la de la reja. En la otra puerta, en cambio, acertó de primera. La casa estaba a oscuras y mientras él cerraba me pidió que encendiera la luz."}]$lira$::jsonb,
  845
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'el-camino-de-sherlock',
  37,
  'Parte 38',
  $lira$[{"type": "p", "text": "—Espero que no esté cortada —dijo. • Empecé a tantear la pared sin encontrar el interruptor. Había avanzado varios pasos hacia la sala a oscuras cuando sentí que alguien surgía de la nada, se abalanzaba sobre mí y tiraba con fuerza de mis brazos hacia atrás. Grité e intenté forcejear, pero me di cuenta de que tenía las manos esposadas en la espalda. Una idea me sacudió: quizás habíamos sorprendido al asesino cuando revisaba la casa en busca de algo que lo incriminaba. Volví a gritar para llamar la atención del fiscal:"}, {"type": "p", "text": "—¡Eyyy, Flores! ..."}, {"type": "p", "text": "Pero en ese momento me tiraron violentamente contra un sillón. Mi cabeza golpeó en el respaldo y lancé un aullido mientras el corazón me saltaba enloquecido. Intentaba pararme otra vez cuando se encendieron las luces. Entonces vi al propio Flores apuntándome con una pistola. En los primeros segundos no entendí nada."}, {"type": "p", "text": "—Pero ,•q ue' ....;, e·E s ta' 1o co..i —¿Loco?-mientras hablaba me obligó a trasladarme a una silla. Vi que tenía una soga en las manos—. No, no estoy loco, Sherlock. Empezó a atarme contra el respaldo."}, {"type": "p", "text": "—Sí, ya había adivinado quién eras. Primero me llamó la atención la dirección del e-mail y después, cuando escribiste que eras muy joven, me acordé. Yo te vi en aquel programa: también soy un fanático de las historias de Holmes. Qué pena que perdiste. Y con una pregunta tan tonta, el nombre de Watson. Supe quién era él antes de que terminará de atarme. Qué imbécil había sido."}, {"type": "p", "text": "—Leguizamón. Usted es Leguizamón."}, {"type": "p", "text": "—¡Exacto! Esta vez acertaste, pero no hay premio."}, {"type": "p", "text": "Se rio mientras me ataba los pies."}, {"type": "p", "text": "—Fue divertido hacer del fiscal. Y caíste: ya te imaginarás que no tengo una oficina en la fiscalía, estaba esperando tu llamada en el descanso de la escalera. Y por supuesto que el que fingió ser mi secretario es un amigo. Tengo muchos amigos en la zona de Tribunales. Entonces sacó un papel y una lapicera de su bolsillo."}, {"type": "p", "text": "—Ahora vas a escribir lo que te diga. Me quitó las esposas, pero eso no me dio demasiada libertad: la soga que me unía a la silla casi no me dejaba respirar."}, {"type": "p", "text": "—¿Me está ... secuestrando? Sonrió."}, {"type": "p", "text": "—Algo así. Escribí: \"Quería resolver este caso —dictó—. Lo lamento\". -~ ue"}, {"type": "p", "text": "....f —Escribí eso, nada más. Y firmá. Después me sacó la hoja, la dobló y volvió a guardarla en su bolsillo. En lugar de las esposas, esta vez me ató las manos con una tira de tela."}, {"type": "p", "text": "—Muy bien, Sherlock. Tengo que decirte que no acertaste en todo: a la china no la maté yo."}, {"type": "p", "text": "—¿Y quién la mató?"}, {"type": "p", "text": "—Qué sé yo —se rio—. Habrá sido la mafia china. En realidad, fue su muerte la que me dio la idea. Tal como vos dijiste: había oído lo de la estación y la confitería, y pensé que esto me ayudaba a armar una buena historia. Tenía que hacer que se unieran varios casos. Recibí algunas ayudas inesperadas, como la bolsa del supermer cado que encontraron en la casa de Reyes. Un detalle encantador. Por eso después dejé una junto a Lucía. Pero a la vieja no quise matarla: eso fue un accidente."}, {"type": "p", "text": "—Un accidente. Seguro."}, {"type": "p", "text": "Se sentó en el sillón y empezó a juguetear con la pistola. Pensé que tenía que hacer algo, pero me había atado tan firmemente que estaba convertido en una especie de matambre, sin posi bilidad alguna de· movimiento."}, {"type": "p", "text": "—Mi objetivo era que pareciera un intento de asesinato: una bala que la roza, la moto, el impermeable ... Alcanzaba con eso. Pero en el momento en que apreté el gatillo la vieja se inclinó a recoger algo y le di en la cabeza. U na lástima. La verdad es que yo sólo quería matar a Lucía. Se lo merecía. ¿Sabés cuánto había heredado la muy perra? Ochocientos mil dólares. Ni ella sabía que su viejo tenía tanta guita. Yo estaba realmente mal y le pedí un préstamo: apenas diez mil. Y me dijo que no podía, que tenía todo invertido. Que mejor me consiguiera un buen trabajo. De modo que decidí hacer un trabajo, pero no el que ella imaginaba. Y salió todo bien. Ya lo tenían a Rosales y nadie estaba muy interesado en seguir buscando, porque así son las cosas acá. Esto no es un libro, nene, y si tienen un culpable están todos contentos. Pero a vos se te ocurrió jugar al detective. En ese momento me di cuenta: no me estaba secuestrando. Era mucho peor. Empecé a gritar, pero no creo que nadie hubiera podido oírme. El tipo se incorporó enseguida y me lanzó un derechazo en la cara que durante unos segundos cumplió la función de dejarme mudo. Después sacó una tela del bolsillo y me amordazó."}, {"type": "p", "text": "—Parece que esto termina con nuestro diá logo, Sherlock De todas formas ya me tenía que ir. Vi que se dirigía hacia la cocina."}, {"type": "p", "text": "—Ahora todo va a ser muy tranquilo —me dijo—. Dejo el gas abierto. Te vas a adormecer. . . Y listo. Después yo vuelvo para ordenar todo: te saco las sogas, te coloco en el piso ... La puerta forzada, y a tu lado, la notita. El suicidio es algo frecuente entre los chicos genios, ¿sabías? Mucha presión."}]$lira$::jsonb,
  875
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'el-camino-de-sherlock',
  38,
  'Parte 39',
  $lira$[{"type": "p", "text": "Desde donde estaba pude ver que abría todas las llaves de gas de la cocina. Después se acercó y me revisó los bolsillos. Se quedó con mi celular y un papel donde yo había anotado su nombre y su teléfono. Entonces recogió sus cosas y se dirigió a la puerta. Antes de salir volvió a mirarme con una media sonrisa."}, {"type": "p", "text": "—Esto es el fin, Sherlock. Au revoir. Pensé que era una línea apropiad.a para que pronunciara el profesor Moriarty en las cata ratas de Reichenbach. Claro que él nunca hubiera dicho Sherlock, sino Mr Holmes. Apenas se cerró la puerta empecé a sacu dirme. Enseguida supe que no tenía sentido: no lograba aflojar ni un milímetro las sogas y corría el riesgo de irme al suelo con la silla. Me sentía furioso. También muerto de miedo, pero sobre todo furioso. Había caído en la trampa como un idiota."}, {"type": "p", "text": "El olor del gas aún era suave, aunque sabía que no tardaría en asfixiarme. Quise pensar en algún episodio de Holmes que me ayudara, pero lo único que me vino a la cabeza fue una frase que dice en el caso de la desaparición de lady Frances Carfax: \"Es una gallina que se ha salido del corral en un mundo de rorros\". Así me sentía yo. Una estúpida gallina cazada por un astuto zorro. Y ese era mi final."}, {"type": "p", "text": "Pero resultó que el zorro no era tan astuto. No se dio cuenta de que una pequeña ventana alta de la cocina estaba abierta, por lo cual el gas jamás iba a llegar a matarme. Por supuesto, con suficiente tiempo podáa haber muerto igual, de sed y de hambre, o bien cuando Leguhamón volviera y opta ra por volarme la cabe-za de un tiro. Pero nada de eso sucedió, porque una hora más tarde yo estaba libre. Fue, debería decir, la hora más extraña de mi vida. Durante los primeros minutos retomé los intentos de liberar mis manos, sin ningún éxito. Entonces me enfrenté a la idea de que estaba a punto de morir. Pensé primero en el golpe que sig nificaría para mis padres. Después imaginé cómo sería mi funeral, quién iría y lo que pensarían de mí, si es que se creían la historia del suicidio. Quise confiar en que Watson sabía lo suficiente para convencer a todo el mundo de que yo no podía haberme sui cidado. Entonces quizá pensarían que había sido un tarado por caer de esa manera en manos de un asesino: parecía tan inteligente, dirían, y terminó así. Luego, dado que pasaban los minutos y el gas sólo me había provocado un leve mareo, empecé a pensar que tal vez se producía un mila gro y yo no me moría. Quizás eso cambiaría com pletamente el curso de mi vida, como suele suceder con los que sobreviven a una guerra o a un naufragio. Pero no tenía muy claro cuál podía ser en mi caso el nuevo curso. Al final, por supuesto, empecé a pensar qué diablos sucedía con ese gas que se olía tan suavemente. Y entonces llegaron. Quizá podría haber muerto igual, pero del susto, porque de pronto se oyó un fuerte estallido en la puerta y, como corridos por el diablo, entraron una decena de policías con chalecos antibalas y armas largas que aullaban y me apuntaban. Cuando terminaron de constatar que en la casá no había nadie más que yo, y que —considerando que estaba convertido en un matambre en medio de la sala- no podía representar un gran peligro, baja ron las armas y procedieron a desatarme. Apenas me quitaron la mordaza le dije al oficial que parecía estar a cargo que Leguizamón era el verdadero asesino· de Belgrano y que tenían que ir en su busca. El tipo me miró con pena y dijo:"}, {"type": "p", "text": "—Sí, hijo, ya vamos a ver eso. Lo que me hizo sentir como el protagonista de esas películas de acción donde al que realmente sabe la verdad nadie le cree. Pero después apareció un flscal —esta vez un fiscal real- y hablamos un rato largo, durante el cual pareció tomarme en serio."}, {"type": "p", "text": "—A Leguizamón lo estábamos investigando —me dijo, lo que nunca sabré si era verdad o un invento para salvar la imagen. Conversando con él supe que el verdadero héroe de la jornada era Watson, a quien le debo la vida. Preocupado por la falta de noticias mías, primero me llamó insistentemente, pero como un idiota yo había apagado el celular después de mandarle el mensaje para evitar que sonara mien tras conversaba con el supuesto fiscal. Entonces fue hasta mi casa, pidió permiso para revisar mi computadora y buscó los mails que yo había intercambiado con el tipo. Se armó de valor y confrontó a mi madre con todo eso, sumado al mensaje de texto que le había enviado. Ella, al borde de la histeria, decidió ir a la policía. Ahí le dijeron que no existía ningún fiscal con ese nombre, que todo parecía indicar que se trataba de un secuestro y que se quedara en la casa esperando la llamada en la que seguramente le pedirían un rescate. Lo cual, por supuesto, la hizo caer en la his teria, ahora de lleno."}]$lira$::jsonb,
  869
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'el-camino-de-sherlock',
  39,
  'Parte 40',
  $lira$[{"type": "p", "text": "Pero por suerte un policía decidió tomarse el asunto en serio. Consideró que quizá yo había ido a la escena de alguno de los crímenes. Descartó el supermercado de Huang y fue directamente a lo de Luisa Reyes, donde una de sus hijas estaba reti rando muebles. Nada inquietante. Por último se acercó a la casa de Bernárdez. Ahí encontró a un vecino a quien le había llamado la atención ver entrar a dos personas en la casa de la chica muerta, donde se suponía que nadie vivía. Fue cuando decidieron forzar la puerta. Después de contar todo lo que sabía, fui examinado por un médico que dijo que, más allá de las huellas del shock emocional y las de la trompada que me había dado Leguizamón, yo parecía estar bien. Entonces llegaron mis padres. Cuando los vi me sentí un poco culpable. Tenían un aspecto bastante penoso, sobre todo mamá, que se había pasado llorando las últimas horas. Me abrazó y sentí su cara húmeda contra la mía. Durante unos momentos me abandoné a sus brazos como cuando era chico. Me di cuenta de que también a mí se me caían las lágrimas y no las podía detener. Me sentía raro, enormemente cansado. Todo mi cuerpo estaba dolorido y flojo como si hubiera corrido una maratón o escalado una monta.fia, aunque sólo había estado atado a una silla. Mis padres querían que les contara todo en ese mismo momento, pero les dije que lo haría de camino a casa. A esa altura, sólo deseaba llegar y meterme en la cama. Fui soltando la historia en el auto, tratando de aparecer lo más inocente posible, aunque evidentemente mi posición no era sencilla. Cuando terminé, tuve que escuchar el largo monólogo de mamá. Me dijo que les había dado el susto de sus vidas y que esta experiencia tenía que enseñarme a dejar atrás el asunto de los crímenes y retomar mi verdadero camino. Si yo quería dar libre el último año de secundaria, tal como había insinuado una vez, ella estaba dispuesta a apoyarme. Así podía entrar antes en la universidad, encontrar un medio y amigos apro piados."}, {"type": "p", "text": "Yo la escuché en silencio. No tenía ganas de contestarle nada, pero cuando estábamos en casa cambié de idea. Antes de meterme en mi habitación le dije que no iba a dar el año libre, que todavía no sabía cuál era mi camino pero que sería el que yo decidiera y que tal vez nunca tendría muchos amigos. Que jamás sería famoso ni ganaría el Premio Nobel."}, {"type": "p", "text": "—¿El qué? —preguntó frunciendo las cejas—. Si yo nunca dije ..."}, {"type": "p", "text": "—El Nobel —insistí antes de cerrar la puerta—. Olvídate."}, {"type": "p", "text": "Dormí doce horas seguidas. Cuando abrí los ojos me sentía extraño, como si estuviese en un lugar desconocido. &a era mi habitación y ahí estaba mi ropa en el suelo, mis libros en la biblioteca y V838 Monocerotis en la pared. Pero había algo distinto. Quizás era que había sobrevivido. O lo que le había dicho a mi madre. Quizás ambas cosas. Salí del dormitorio y la vi haciendo zap ping en la televisión."}, {"type": "p", "text": "—Vení —me llamó—, están por dar un informe sobre el caso."}, {"type": "p", "text": "Me senté junto a ella y me rodeó los hombros con el brazo, señal de que no estaba enojada. En la pantalla la placa sobreimpresa decía: \"Un adolescente dejó en ridículo a toda la policía''."}, {"type": "p", "text": "—Ya grabé lo que pasaron en otros canales —me informó en voz baja."}, {"type": "p", "text": "El periodista, de pie frente a la casa de Lucía Bernárdez, explicaba que allí había estado secuestrado el chico de catorce años que había descubierto al verdadero asesino de Belgrano. Y que gracias a él la policía ya lo había detenido. La mayor parte del informe se dedicaba a regodearse en el papelón de los investigadores al ser superados por un detective amateur y adolescente apodado Sherlock por sus amigos."}, {"type": "p", "text": "—No saben mi nombre —deduje."}, {"type": "p", "text": "—No, el juez ordenó que se mantuviera en resguardo tu identidad por ser menor de edad."}, {"type": "p", "text": "La noticia me dio una enorme tranquili dad. Le dije a mamá que iba a desayunar."}, {"type": "p", "text": "—Tenés algunos mensajes —me informó—. Arturo pidió que lo llames. Y luego esa chica ..."}, {"type": "p", "text": "—¿Quién?"}, {"type": "p", "text": "—Violeta. La Chica Araña. Dijo que había oído la historia y pensó que podías ser vos por una conversación que tuvieron —sus ojos me interrogaron—. ¿La viste?"}, {"type": "p", "text": "—Sí, de casualidad —admití, intentando no mostrar mucho interés—. ¿Dijo algo más?"}, {"type": "p", "text": "—Dejó su teléfono."}, {"type": "p", "text": "Me extendió un papel que miré durante todo el desayuno. Después me encerré en mi dor mitorio y lo llamé a Watson."}, {"type": "p", "text": "—Me salvaste la vida —dije apenas aten dió—. Gracias."}, {"type": "p", "text": "—Sí, Sherlock, estuviste un poco idiota. Claro que también estuviste brillante: resolviste el caso. Sos un genio."}, {"type": "p", "text": "Cerré los ojos durante un par de segundos y me permití disfrutar de sus halagos."}, {"type": "p", "text": "—No todo —le aclaré después—. El tipo dijo que a la china no la mató él y puede ser cierto. ¿Te acordás de que en ese caso no hubo ninguna moto? En verdad, solo tenía en común el cali bre del arma, que es bastante vulgar."}, {"type": "p", "text": "—Pero igual sos un genio. Lo descubriste solo. ¿No te tienta que se sepa?"}, {"type": "p", "text": "—¿Qué cosa?"}, {"type": "p", "text": "—Quesos vos. Que el chico del que habla todo el país es Francisco Méndez."}, {"type": "p", "text": "—No —le dije—, para nada. Ya sabés, Watson: \"Yo entro en el juego por puro amor al Juego ."}, {"type": "p", "text": "—¿Eso es una cita?"}, {"type": "p", "text": "—Sí, pero no me acuerdo de qué libro."}, {"type": "p", "text": "—Mejor —se rio—, mucho mejor. Después de cortar con él volví a mirar el papel donde estaba el número de Violeta y decidí que la iba a llamar. Pero no en ese momento. Igual, la decisión me puso bastante nervioso. Observé un rato a V838 Monocerotis, que ese día parecía más brillante."}, {"type": "p", "text": "—Mon —le dije—, mi cerebro funciona. Entonces, para relajarme, me dediqué a leer un buen rato un libro que habla sobre los agujeros negros. Creo que me sentí feliz. -. . ' ~· .... : . . .. .,.,,-: - ~. · . , , . . ~ . - .. : - /'. .. ~~ r',"}]$lira$::jsonb,
  1022
);


-- Cuadra el catalogo con lo cargado.
update public.books
set chapter_count = (select count(*) from public.chapters c where c.book_id = 'el-camino-de-sherlock'),
    minutes_to_read = 145
where id = 'el-camino-de-sherlock';

-- Dinamicas. Ninguna tiene respuesta correcta y todas apuntan al lector.
insert into public.activities (book_id, chapter_id, kind, prompt, hint)
select 'el-camino-de-sherlock', id, 'reflexionar',
       'En su casa dan por hecho que va a hacer algo enorme, y el ni lo pidio ni lo quiere. Hay algo que esperen de ti que tu no elegiste?',
       'Una frase basta. Nadie mas la va a leer.'
from public.chapters where book_id = 'el-camino-de-sherlock' and position = 1;

