-- Ahora si: publicar.
update public.books set is_published = true where id = 'el-camino-de-sherlock';

-- Comprobacion.
select b.title, b.chapter_count, b.minutes_to_read, b.is_published,
       (select count(*) from public.chapters c where c.book_id = b.id) as segmentos,
       (select count(*) from public.activities a where a.book_id = b.id) as dinamicas
from public.books b where b.id = 'el-camino-de-sherlock';
